// ---------- T4 De Deo Trino, lessons 2–7 (Scripture, councils, ST I qq.27–43) ----------
// Summa quotations: Dominican translation (1920, public domain), checked by script against the New Advent text. Scripture: Douay-Rheims.
addTerms([
 {id:"homoousios",t:"Homoousios",la:"consubstantialis",d:"Trinity",b:"'Of one substance': the word Nicaea used to say the Son is God in exactly the same sense as the Father.",p:"Greek homo-ousios, 'same in being'. Defined at Nicaea (325) against Arius; the Latin is consubstantialis. It excludes both a created Son and a merely similar (homoiousios) one.",ex:"\"God from God, light from light, true God from true God… consubstantial with the Father\" (Creed).",where:"Nicaea (325), DS 125",ccc:"242",conf:"Homoiousios, 'of like substance', a compromise word of the 350s.",rel:["consubstantial","arianism"],lesson:"t4l2",alias:["homoousios","homoousion","of one substance"]},
 {id:"hypostasis",t:"Hypostasis",la:"hypostasis / subsistentia",d:"Trinity",b:"A concrete subsisting individual; in the Trinity, the Greek word for 'person'.",p:"In Cappadocian usage, the distinct subsistent (Father, Son, Spirit) as opposed to the common ousia. Thomas: \"hypostasis\" signifies the individual substance, \"person\" adds rational nature (ST I q.29 a.2).",ex:"One ousia, three hypostaseis (Council of Alexandria, 362; Constantinople, 381).",where:"ST I q.29 a.2",ccc:"252",conf:"Ousia (essence), with which it was once used interchangeably, causing confusion before 362.",rel:["person","suppositum"],lesson:"t4l2",alias:["hypostases","hypostaseis"]},
 {id:"economy",t:"Economy / theology",la:"oikonomia / theologia",d:"Trinity",b:"God's works in history (economy) versus God's inner life (theology).",p:"The Fathers distinguish theologia, the mystery of God's inmost life, from oikonomia, the works by which God reveals himself and communicates his life. \"Through the oikonomia the theologia is revealed to us\" (CCC 236).",ex:"The sending of the Son (economy) reveals his eternal generation (theology).",where:"CCC 236",ccc:"236",conf:"'Economy' in the modern financial sense.",rel:["mission","procession"],lesson:"t4l2",alias:["economic Trinity","immanent Trinity","oikonomia"]},
 {id:"psych-analogy",t:"Psychological analogy",la:"analogia psychologica",d:"Trinity",b:"Understanding the Trinity through the mind that knows and loves itself.",p:"Augustine's analogy (De Trinitate IX–XV), refined by Thomas: as the mind conceives an inner word in knowing and an impulse of love in willing, so in God the Word proceeds by intellect and the Spirit by will (ST I q.27; qq.34, 37).",ex:"Mind, its knowledge, its love; or memory, understanding, will.",where:"Augustine, De Trin. IX–XV; ST I q.93 a.6",ccc:"",conf:"A proof of the Trinity; it is a fitting likeness only.",rel:["verbum-mentis","procession"],lesson:"t4l3",alias:["psychological analogy","mind, knowledge and love"]},
 {id:"image-dei",t:"Image (of God)",la:"imago",d:"Trinity",b:"A likeness that comes from what it is like, and resembles it in kind.",p:"Image requires likeness in species (or a sign of species) and origin from the one imaged. Properly the Son is the Image of the Father (Col 1:15; ST I q.35 a.2); man is made 'to the image', an imperfect image in his intellectual nature (q.93).",ex:"A son is the image of his father; a footprint is only a trace.",where:"ST I q.35; q.93",ccc:"241, 1701",conf:"Any likeness at all (a vestige or trace).",rel:["verbum-mentis"],lesson:"t4l3",alias:["Image","image of God","imago Dei"]},
 {id:"notion",t:"Notion",la:"notio",d:"Trinity",b:"A mark by which we know and distinguish a divine person.",p:"\"The proper idea whereby we know a divine Person\" (ST I q.32 a.3). There are five: innascibility, paternity, filiation, common spiration, procession. Four are relations; three are personal properties (paternity, filiation, procession).",ex:"Innascibility (being unbegotten) marks the Father.",where:"ST I q.32 aa.2–3",ccc:"",conf:"A person; notions are what distinguish persons.",rel:["relation-divine","person"],lesson:"t4l4",alias:["notion","notions","innascibility","unbegotten"]},
 {id:"notional-act",t:"Notional act",la:"actus notionalis",d:"Trinity",b:"The acts by which the persons proceed: begetting and spirating.",p:"Acts attributed to the persons to signify their order of origin: to beget (Father), to be begotten (Son), to spirate (Father and Son), to proceed (Spirit). Unlike essential acts (creating, knowing), they are proper to persons (ST I q.41).",ex:"The Father begets; the Father and Son spirate.",where:"ST I q.41",ccc:"",conf:"Essential acts, common to all three.",rel:["procession","notion"],lesson:"t4l4",alias:["notional act","notional acts","spirate","spiration"]},
 {id:"filioque",t:"Filioque",la:"Filioque",d:"Trinity",b:"'And the Son': the Latin teaching that the Spirit proceeds from the Father and the Son.",p:"The Spirit proceeds eternally from the Father and the Son as from one principle and by one spiration (Lyons II, 1274, DS 850; Florence, 1439, DS 1300–1302). Added to the Latin Creed in Spain (Toledo III, 589), accepted at Rome c.1014. The Greek 'from the Father through the Son' is held to express the same faith when rightly understood (Florence; CCC 248).",ex:"\"…who proceeds from the Father and the Son\" (Latin Creed).",where:"ST I q.36 aa.2–4",ccc:"246–248",conf:"Two principles or two spirations, which the Church rejects.",rel:["procession","relation-divine"],lesson:"t4l5",alias:["Filioque","and the Son","per Filium","through the Son"]},
 {id:"gift",t:"Gift (personal name)",la:"donum",d:"Trinity",b:"A proper name of the Holy Spirit: the first gift, because he proceeds as Love.",p:"\"Love has the nature of a first gift, through which all free gifts are given\"; so the Spirit, who proceeds as Love, is properly called Gift (ST I q.38 a.2).",ex:"\"The charity of God is poured forth in our hearts, by the Holy Ghost who is given to us\" (Rom 5:5).",where:"ST I q.38",ccc:"733",conf:"The created gifts of the Spirit (wisdom, understanding…), which he gives.",rel:["mission","charity"],lesson:"t4l5",alias:["Gift","first gift"]},
 {id:"indwelling",t:"Indwelling of the Trinity",la:"inhabitatio",d:"Trinity",b:"The presence of the Father, Son and Spirit in the soul in grace, as known and loved.",p:"By sanctifying grace the whole Trinity dwells in the just as in a temple (John 14:23); the Son and Spirit are said to be sent there because they come from another (ST I q.43 aa.3, 5).",ex:"\"We will come to him and will make our abode with him\" (John 14:23).",where:"ST I q.43",ccc:"260, 1997",conf:"God's general presence by essence, presence and power.",rel:["mission","omnipresence","grace"],lesson:"t4l7",alias:["indwelling","dwells in","abode"]}
]);

mkLessons("t4",[
// ===================== L2 THE TRINITY REVEALED =====================
{id:"t4l2",ord:2,code:"T4 · Lesson 2",title:"The Trinity revealed: Scripture, the Fathers and the councils",
 outcomes:["Trace the revelation of the Trinity from Old Testament anticipations to the triadic faith of the New Testament.","Explain the distinction between 'economy' and 'theology' and why the Trinity is known through the economy.","Set out the Arian crisis and what Nicaea (325) and Constantinople (381) defined, including homoousios.","Explain how the Cappadocians fixed the terms ousia and hypostasis, and Tertullian and Augustine the Latin terms.","Identify the later magisterial statements (Athanasian Creed, Lateran IV, Florence) that Thomas's treatise presupposes."],
 prereq:["homoousios","hypostasis","economy","arianism","sabellianism","consubstantial","revelation"],
 recall:[
  ["t4","Why can reason not prove the Trinity, according to ST I q.32 a.1?","Reason knows God only from creatures, as cause from effects; creative power is common to the three persons, so it shows the unity of the essence, not the distinction of persons."],
  ["t1","How is revelation transmitted, according to Dei Verbum?","By Scripture and Tradition, which form one sacred deposit, authentically interpreted by the living Magisterium (DV 9–10)."],
  ["f9","When and why was the Council of Nicaea called?","In 325, by Constantine, to resolve the Arian controversy over whether the Son is true God."],
  ["t3l10","Why does Thomas treat the one God (qq.2–26) before the three persons?","Because the processions of the Son and Spirit are grounded in God's operations of knowing and willing (qq.14, 19), which must be understood first."]],
 reading:{primary:[["Creed of Nicaea (325) and of Constantinople (381)",'https://www.papalencyclicals.net/councils/ecum02.htm'],["The Athanasian Creed (Quicumque)",'https://www.newadvent.org/cathen/02033b.htm'],["CCC 232–267",'https://www.vatican.va/archive/ENG0015/__P17.HTM'],["Gregory of Nazianzus, Oration 31 (Fifth Theological Oration, on the Holy Spirit)",'https://www.newadvent.org/fathers/310231.htm'],["Basil, On the Holy Spirit, chs 16–18",'https://www.newadvent.org/fathers/3203.htm']],
  secondary:["Ayres, L. (2004) Nicaea and its Legacy: An Approach to Fourth-Century Trinitarian Theology. Oxford: Oxford University Press.","Hanson, R.P.C. (1988) The Search for the Christian Doctrine of God: The Arian Controversy 318–381. Edinburgh: T&T Clark.","Kelly, J.N.D. (1977) Early Christian Doctrines. 5th edn. London: A&C Black, chs 4–5, 9–10.","Emery, G. (2011) The Trinity: An Introduction to Catholic Doctrine on the Triune God, ch. 1.","Wainwright, A.W. (1962) The Trinity in the New Testament. London: SPCK."]},
 scripture:[["Matthew 28:19, baptizing them in the name",null],["2 Corinthians 13:13, the grace… the charity… the communication",null],["John 1:1, the Word was with God, and the Word was God",null],["John 15:26, the Spirit… who proceedeth from the Father","j15-26"]],
 sections:[
 {id:"s1",h:"1. How the Trinity was revealed: through the economy",html:`<p>The Trinity is the central mystery of Christian faith (CCC 234). It is not a deduction from philosophy but a truth God showed by <em>sending</em> his Son and his Spirit. The Fathers distinguished two words:</p>
<div class="tablewrap"><table class="t"><thead><tr><th>Theologia</th><th>Oikonomia</th></tr></thead><tbody>
<tr><td>God's inner life: who God is eternally</td><td>God's works in history: creation, covenant, Incarnation, Pentecost, Church</td></tr>
<tr><td>Known only because it is revealed in the economy</td><td>Revealing: \"Through the oikonomia the theologia is revealed to us\" (CCC 236)</td></tr></tbody></table></div>
${RC("t4",`<p>In L1 you met the <strong>missions</strong>: a divine person sent is his eternal procession plus a new presence in creatures. The economy is the missions seen from history. That is why the order of revelation runs: the Father sends the Son; the Father and the Son send the Spirit; and from these sendings the Church learned the eternal processions.</p>`)}
<p><strong>Old Testament anticipations.</strong> Read in the light of Christ (the allegorical sense), the Fathers saw hints: the plural \"Let us make man to our image\" (Gen 1:26); the three visitors at Mamre (Gen 18); the Word by which the heavens were made (Ps 32:6); personified Wisdom, \"brightness of eternal light… the image of his goodness\" (Wis 7:26); the Spirit of the Lord. None of these alone teaches the Trinity; together they prepare for it.</p>
${RC("f1",`<p>These are readings in the <strong>allegorical sense</strong> from F1: things of the Old Law signifying those of the New. Thomas insists that argument rests on the <strong>literal sense</strong> (q.1 a.10 ad 1); so the doctrine is proved from the New Testament, and the Old is read as foreshadowing.</p>`)}`,
  check:Q("According to CCC 236, how do we come to know God's inner life (theologia)?",[["By philosophy","Reason cannot reach the Trinity."],["Through his works in history (oikonomia)","Correct."],["By private revelations","No."]],1)},
 {id:"s2",h:"2. The New Testament: one God, Father, Son and Spirit",html:`<p>The New Testament keeps the strict monotheism of Israel (\"to us there is but one God, the Father… and one Lord Jesus Christ\", 1 Cor 8:6) while placing Jesus and the Spirit within the one divine identity.</p>
<ul><li><strong>Triadic formulas.</strong> \"Baptizing them in the name of the Father and of the Son and of the Holy Ghost\" (Matt 28:19): one name, three. \"The grace of our Lord Jesus Christ and the charity of God and the communication of the Holy Ghost be with you all\" (2 Cor 13:13).</li>
<li><strong>The Son is God.</strong> \"In the beginning was the Word: and the Word was with God: and the Word was God\" (John 1:1). \"Before Abraham was made, I AM\" (John 8:58). \"Being in the form of God, thought it not robbery to be equal with God\" (Phil 2:6). \"I and the Father are one\" (John 10:30).</li>
<li><strong>The Son is distinct.</strong> 'With God' (John 1:1); the Son prays to the Father (John 17:5: \"glorify thou me, O Father, with thyself, with the glory which I had, before the world was\").</li>
<li><strong>The Spirit is personal and divine.</strong> He teaches, testifies, can be grieved; \"the Paraclete… whom I will send you from the Father, the Spirit of truth, who proceedeth from the Father\" (John 15:26); your members are his temple (1 Cor 6:19), and only God has a temple.</li></ul>
${RC("t2",`<p>From T2 and T2b: we read these texts in their <strong>literal sense</strong> and as a canonical whole. The doctrine of the Trinity is not one verse but the shape of the whole New Testament witness, which the councils formulated.</p>`)}
<div class="co warn"><div class="co-h">A textual note</div><p>The Douay-Rheims of 1 John 5:7 reads \"there are three who give testimony in heaven, the Father, the Word, and the Holy Ghost. And these three are one.\" This 'Johannine comma' is absent from the early Greek manuscripts and is now generally held by Catholic scholars to be a later Latin gloss. The Holy Office (1897) cautioned against denying its authenticity; its 1927 declaration allowed scholars to examine and reject it. The doctrine does not depend on it.</p></div>`,
  check:Q("Which text gives one 'name' for Father, Son and Holy Spirit?",[["John 1:1","It concerns the Word."],["Matthew 28:19","Correct: 'in the name' (singular) of all three."],["1 Corinthians 6:19","It concerns the Spirit's temple."]],1)},
 {id:"s3",h:"3. The Arian crisis and Nicaea (325)",html:`<p><strong>Two early errors.</strong> <em>Modalism</em> (Sabellius, early 3rd c.): one person who appears as Father, Son or Spirit. <em>Subordinationism</em>: the Son is divine, but less. Tertullian (<em>Adversus Praxean</em>, c.213) answered the modalists and coined the Latin vocabulary: <em>trinitas</em>, <em>una substantia, tres personae</em>.</p>
<p><strong>Arius</strong> (c.318), a priest of Alexandria, argued: God is unbegotten and unique; whatever is begotten is not God in the same sense; so the Son is the first and greatest creature. His slogan: \"there was when he was not\". Scripture texts like Proverbs 8:22 (\"The Lord possessed me in the beginning of his ways\") were read as the creation of Wisdom.</p>
${RC("t4",`<p>L1 (q.27 a.1) gave Thomas's diagnosis: Arius took procession as an <strong>outward</strong> act, an effect from a cause. Then the Son must be a creature. The answer is an <strong>inward</strong> procession, like the word in the mind.</p>`)}
<p><strong>Nicaea (325)</strong> answered with a creed:</p>
<div class="quote">"…the Son of God, begotten from the Father, only-begotten, that is from the substance of the Father, God from God, light from light, true God from true God, begotten not made, consubstantial (homoousios) with the Father…"<span class="src">Creed of Nicaea (325), DS 125; tr. after Tanner, Decrees of the Ecumenical Councils (1990)</span></div>
<p>The key word, <em>homoousios</em>, was not scriptural; the bishops used it because every scriptural phrase was being re-read by the Arians. It says: the Son is God in exactly the same sense as the Father. 'Begotten not made' separates generation from creation.</p>
<p><strong>After Nicaea</strong>, decades of conflict followed. Athanasius (exiled five times) defended homoousios; some proposed <em>homoiousios</em>, 'of like substance'. The Council of Alexandria (362) clarified the terms and reconciled many.</p>`,
  check:Q("What did 'begotten not made' in the Nicene Creed exclude?",[["Modalism","Not directly."],["The Arian view that the Son is a creature","Correct."],["The divinity of the Spirit","Not the topic."]],1)},
 {id:"s4",h:"4. The Spirit and the terms: the Cappadocians and Constantinople (381)",html:`<p>Once the Son's divinity was secured, some (the 'Pneumatomachi', fighters against the Spirit) denied the Spirit's. Basil of Caesarea (<em>On the Holy Spirit</em>, 375) argued from the liturgy: the Church glorifies the Spirit <em>with</em> the Father and the Son, and baptizes in his name; so he is one in honour and nature. Gregory of Nazianzus (<em>Oration</em> 31, 380) argued that revelation is gradual: the Old Testament proclaimed the Father clearly and the Son obscurely; the New manifested the Son and suggested the Spirit's divinity; now the Spirit dwells among us and shows himself more clearly.</p>
<p><strong>The terms.</strong> The Cappadocians (Basil, Gregory of Nazianzus, Gregory of Nyssa) fixed the formula: <strong>one <em>ousia</em>, three <em>hypostaseis</em></strong>. <em>Ousia</em> is what is common (essence); <em>hypostasis</em> is what is distinct (the concrete subsistent). Before this, the two words were often used as synonyms, which caused much of the confusion.</p>
<p><strong>Constantinople I (381)</strong> expanded the Creed: the Holy Spirit is \"the Lord and giver of life, who proceeds from the Father, who with the Father and the Son is worshipped and glorified, who spoke through the prophets\" (DS 150). Without using homoousios of the Spirit, it gives him what belongs to God alone: lordship, life-giving, worship.</p>
${RC("t16a",`<p>Basil's argument is an example of <strong>lex orandi, lex credendi</strong> (T16a): the way the Church prays shows what she believes. The doxology "Glory be to the Father, and to the Son, and to the Holy Spirit" was itself a confession of faith.</p>`)}
${RC("t3l2",`<p>Why must the persons share one <em>ousia</em> and not merely a 'kind' as three men do? Because God is <strong>simple</strong> (L2): his nature is identical with him. Three men are three beings of one kind; the three persons are one being.</p>`)}`,
  check:Q("The Cappadocian formula is…",[["one hypostasis, three ousiai","Reversed."],["one ousia, three hypostaseis","Correct."],["one person, three natures","No."]],1)},
 {id:"s5",h:"5. The Latin tradition and the later definitions",html:`<p><strong>Augustine</strong>'s <em>De Trinitate</em> (c.399–419) set the Western agenda. Books I–IV prove the equality of the persons from Scripture; V–VII treat relation (\"what is said relatively\" is neither substance nor accident); VIII–XV seek the image of the Trinity in the mind that remembers, understands and loves itself. Thomas's treatise is largely a systematisation of Augustine.</p>
<p><strong>The 'Athanasian' Creed</strong> (<em>Quicumque</em>, Latin, c.500, not by Athanasius) gives the classic balance: \"we worship one God in Trinity, and Trinity in Unity; neither confounding the Persons, nor dividing the Substance\" (Book of Common Prayer translation, public domain).</p>
<div class="tablewrap"><table class="t"><thead><tr><th>Council / text</th><th>Date</th><th>What it adds</th></tr></thead><tbody>
<tr><td>Toledo XI</td><td>675</td><td>A detailed Trinitarian creed: the persons are relative names; each is wholly God (DS 525–532)</td></tr>
<tr><td>Lateran IV</td><td>1215</td><td>Against Joachim of Fiore: the divine essence neither begets nor is begotten; there is a Trinity, not a quaternity (DS 803–806)</td></tr>
<tr><td>Lyons II</td><td>1274</td><td>The Spirit proceeds from Father and Son as from one principle, by one spiration (DS 850)</td></tr>
<tr><td>Florence</td><td>1439–42</td><td>Union with the Greeks; 'through the Son'; \"in God all is one where there is no opposition of relation\" (DS 1300–1302, 1330)</td></tr></tbody></table></div>
<p>Thomas wrote before Florence but after Lateran IV, which he cites at q.39 a.5 against Joachim.</p>
<div class="co bridge"><div class="co-h">Psychology · the relational person</div><p>The Trinitarian debates gave the West the concept of <em>person</em> as someone who is what he is <em>in relation</em>. Ratzinger (1990, 'Concerning the notion of person in theology', <em>Communio</em>, 17(3), pp. 439–454) traces how this theological concept shaped modern ideas of personhood. Relational models in psychology (attachment theory; relational-cultural therapy) echo it: the self develops in and through relationships (P5).</p></div>`,
  check:Q("Which council, against Joachim of Fiore, taught that there is a Trinity in God but not a quaternity?",[["Nicaea","No."],["Lateran IV (1215)","Correct: DS 803–806."],["Florence","No."]],1)}
 ],
 quiz:[
  Q("Theologia and oikonomia refer to…",[["Old and New Testaments","No."],["God's inner life and his works in history","Correct: CCC 236."],["philosophy and faith","No."],["East and West","No."]],1,"CCC 236",{bloom:"Remember",terms:["economy"],diff:1}),
  Q("Who coined the Latin formula 'una substantia, tres personae'?",[["Augustine","Later."],["Tertullian","Correct: Adversus Praxean, c.213."],["Thomas","No."],["Athanasius","He wrote in Greek."]],1,"Tertullian",{bloom:"Remember",terms:[],diff:2}),
  Q("'There was when he was not' is a slogan of…",[["Sabellius","No."],["Arius","Correct."],["Nestorius","No."],["Athanasius","He opposed it."]],1,"Arius",{bloom:"Remember",terms:["arianism"],diff:1}),
  Q("Homoousios means…",[["of like substance","That is homoiousios."],["of one (the same) substance","Correct."],["three gods","No."],["one person","No."]],1,"Nicaea, DS 125",{bloom:"Remember",terms:["homoousios"],diff:1}),
  Q("Why did Nicaea use a non-scriptural word?",[["To replace Scripture","No."],["Because the Arians re-read every scriptural phrase in their sense","Correct."],["Because Greek was required","No."],["By accident","No."]],1,"Nicaea",{bloom:"Understand",terms:["homoousios"],diff:2}),
  Q("Basil's main argument for the Spirit's divinity in 'On the Holy Spirit' was from…",[["philosophy","No."],["the liturgy: the Spirit is glorified with the Father and the Son","Correct."],["miracles","No."],["papal decree","No."]],1,"Basil, De Spiritu Sancto",{bloom:"Understand",terms:["lex-orandi"],diff:2}),
  Q("Constantinople I (381) called the Holy Spirit…",[["homoousios","It did not use that word of the Spirit."],["the Lord and giver of life, worshipped and glorified with the Father and the Son","Correct: DS 150."],["the Son of the Father","No."],["the first creature","No."]],1,"DS 150",{bloom:"Remember",terms:[],diff:2}),
  Q("Gregory of Nazianzus explained the slow revelation of the Spirit's divinity by…",[["the Spirit's inferiority","No."],["the gradual pedagogy of revelation: Father, then Son, then Spirit","Correct: Oration 31."],["the absence of the Spirit in Scripture","No."],["papal teaching","No."]],1,"Oration 31",{bloom:"Understand",terms:[],diff:2}),
  Q("The 'Johannine comma' (1 John 5:7) is…",[["in all Greek manuscripts","No."],["generally held to be a later Latin gloss; the doctrine does not depend on it","Correct."],["defined as authentic by Trent","No."],["Thomas's main proof","No."]],1,"1 John 5:7",{bloom:"Evaluate",terms:[],diff:3}),
  Q("Which council stated that the Spirit proceeds 'as from one principle, by one spiration'?",[["Nicaea","No."],["Lyons II (1274)","Correct: DS 850."],["Chalcedon","No."],["Vatican II","No."]],1,"DS 850",{bloom:"Remember",terms:["filioque"],diff:2})
 ],
 construct:{q:"Whether there is procession in God?",ref:"ST I q.27 a.1",
  model:{obj:"It seems not: procession signifies outward movement, and in God there is nothing movable or extraneous; further, everything that proceeds differs from its source, but in God there is no diversity.",sc:"\"From God I proceeded\" (John 8:42).",resp:"Scripture uses names of procession in God. Arius took procession as an effect from a cause, making Son and Spirit creatures; Sabellius as the cause going out to its effects, making them modes. Both take procession as an outward act. But there is also an action that remains in the agent, above all understanding, in which a word proceeds within the mind and remains in it. So procession in God is to be understood as the procession of an intelligible word from the speaker, which remains in him.",rep:"Procession in God is not local or outward motion but immanent emanation. What proceeds inwardly by intelligible procession need not be diverse: the more perfectly it proceeds, the more it is one with its source."},
  rubric:["Objection argues from motion or diversity.","Sed contra quotes John 8:42 (or another text of procession).","Respondeo names Arius' and Sabellius' readings and their common error.","Respondeo introduces immanent action and the inner word.","Reply: inward procession implies unity, not diversity."]},
 drill:{title:"Put the milestones in order",parts:["Tertullian, Adversus Praxean (c.213)","Arius' teaching in Alexandria (c.318)","Council of Nicaea (325)","Council of Alexandria clarifies the terms (362)","Basil, On the Holy Spirit (375)","Council of Constantinople I (381)","Augustine, De Trinitate (c.399–419)","Lateran IV against Joachim (1215)"]},
 connections:`<p><strong>Back.</strong> F9 (councils), T1 (revelation and Tradition), T2/T2b (reading Scripture), T4 L1 (Thomas's synthesis), T16a (lex orandi).</p><p><strong>Forward.</strong> L3 develops the psychological analogy; L4 the vocabulary of person; L5 the Filioque. T11 repeats the same pattern for Christ: Ephesus and Chalcedon fix 'one person, two natures'.</p><p><strong>Apologetics.</strong> The disputations on Arianism, the Filioque and Jehovah's Witness readings of John 1:1 apply this lesson.</p>`},

// ===================== L3 WORD AND IMAGE =====================
{id:"t4l3",ord:3,code:"T4 · Lesson 3",title:"The Word and the Image: the psychological analogy (qq.27, 34–35)",
 outcomes:["Explain the inner word (verbum mentis) and why the procession of the Word is immanent and a true generation (q.27 aa.1–2).","Explain why only two processions exist, by intellect and will (q.27 aa.3–5).","Show why 'Word' is a personal name, the proper name of the Son, and why it implies relation to creatures (q.34).","Explain why 'Image' is proper to the Son (q.35), and how man is made to the image of the Trinity.","Evaluate the strengths and limits of Augustine's psychological analogy."],
 prereq:["verbum-mentis","psych-analogy","image-dei","procession","intellect","will"],
 recall:[
  ["t3l7","How does God know himself and all things?","Through himself, by one act identical with his being; knowing himself as cause, he knows all things (q.14 aa.2, 5)."],
  ["t3l8","Why is there will in God?","Because will follows upon intellect: every intellectual nature tends to the good it knows (q.19 a.1)."],
  ["f5","What does the intellect produce in understanding?","An inner word or concept, in which it understands the thing; the intellect is made actual by the form of the thing understood."],
  ["t4l2","What was Arius' error about procession?","He took it as an outward act, an effect from a cause, so the Son would be a creature."]],
 reading:{primary:[["ST I q.27 aa.1–5 (procession)",NA("1027.htm")],["ST I q.34 aa.1–3 (Word)",NA("1034.htm")],["ST I q.35 aa.1–2 (Image)",NA("1035.htm")],["ST I q.93 aa.5–8 (man as image of the Trinity)",NA("1093.htm")],["Augustine, De Trinitate IX and XV",'https://www.newadvent.org/fathers/130109.htm']],
  secondary:["Emery, G. (2007) The Trinitarian Theology of Saint Thomas Aquinas, chs 4, 7.","Lonergan, B. (1997) Verbum: Word and Idea in Aquinas. Toronto: University of Toronto Press.","Paissac, H. (1951) Théologie du Verbe: saint Augustin et saint Thomas. Paris: Cerf.","Ayres, L. (2010) Augustine and the Trinity. Cambridge: Cambridge University Press."]},
 scripture:[["John 1:1–3, In the beginning was the Word","j1-1"],["Colossians 1:15, the image of the invisible God",null],["Hebrews 1:3, the brightness of his glory and the figure of his substance",null],["Wisdom 7:26, the brightness of eternal light",null]],
 sections:[
 {id:"s1",h:"1. The inner word: why a procession can stay inside (q.27 aa.1–2)",html:`<p>L1 and L2 showed the problem: Arius and Sabellius both pictured procession as an <em>outward</em> act. Thomas's solution begins from our own minds. When I understand something, a <strong>word</strong> is formed in me: not the spoken word, but the concept in which I grasp the thing.</p>
<p>Thomas distinguishes three senses of 'word' (q.34 a.1): the spoken sound, the imagined sound, and first and chiefly the interior concept of the mind, which the spoken word signifies. This inner word:</p>
<ul><li>proceeds from the knower, by the very act of knowing;</li>
<li>remains within the knower;</li>
<li>is a likeness of what is known;</li>
<li>is more perfectly one with its source the more perfectly it is understood.</li></ul>
${RC("f5",`<p>F5 described the intellect forming a <strong>concept</strong> after abstracting from the phantasm. Thomas now uses that ordinary act as a window: here is a procession that does not go outside, produce a different thing, or divide the source.</p>`)}
<p><strong>A true generation (a.2).</strong> Generation in the strict sense is \"the origin of a living being from a conjoined living principle\" by way of likeness in nature. The Word proceeds by intellectual action (a vital operation), from a conjoined principle, as the likeness of what is understood, and in the same nature, since in God to understand and to be are one. So the procession of the Word is truly generation, and he who proceeds is truly Son.</p>`,
  check:Q("Which feature of the inner word answers Arius?",[["It is spoken aloud","No."],["It proceeds yet remains within the knower, one with it","Correct."],["It is a sound","No."]],1)},
 {id:"s2",h:"2. Two processions, and only two (q.27 aa.3–5)",html:`<p>Procession in God follows an action that remains in the agent. In an intellectual nature there are two such actions: <strong>understanding</strong> and <strong>willing</strong> (a.5). Sensing is also immanent, but it is not in God.</p>
<div class="tablewrap"><table class="t"><thead><tr><th></th><th>Intellect</th><th>Will</th></tr></thead><tbody>
<tr><td>What proceeds</td><td>A word: the likeness of the thing known in the knower</td><td>An impulse or 'impression' of love: the beloved in the lover, moving him toward it</td></tr>
<tr><td>Mode</td><td>By way of likeness</td><td>By way of impulse (inclination)</td></tr>
<tr><td>Is it generation?</td><td>Yes: the Son</td><td>No: love does not proceed as a likeness of its source (a.4)</td></tr>
<tr><td>Name</td><td>Word, Son, Image</td><td>Love, Gift, Holy Spirit; the procession has no proper name, so we call it 'spiration'</td></tr></tbody></table></div>
${RC("t3l7",`<p>L7 and L8 of T3 studied God's <strong>knowledge</strong> (q.14) and <strong>will</strong> (q.19). Here they become the ground of the two processions. That is why De Deo Uno comes first: you cannot understand the Word without God's self-knowledge, or the Spirit without God's love.</p>`)}
<p><strong>Why the order?</strong> Love presupposes knowledge: nothing is loved unless first known. So the procession of Love presupposes the procession of the Word. This is the root of the Latin teaching that the Spirit proceeds from the Son as well as the Father (q.36 a.2; L5).</p>`,
  check:Q("Why is the procession of love not 'generation'?",[["Because love is weaker","No."],["Because love proceeds as an impulse, not as a likeness of its source","Correct: q.27 a.4."],["Because the Spirit has no source","He proceeds from Father and Son."]],1)},
 {id:"s3",h:"3. 'Word' is the Son's proper name (q.34)",html:`<p><strong>A personal, not essential name (a.1).</strong> 'Word' signifies something that proceeds from another, so it names a person, not the essence. The essence does not proceed; the Son does.</p>
<p><strong>Proper to the Son (a.2).</strong> \"'Word,' said of God in its proper sense, is used personally, and is the proper name of the person of the Son. For it signifies an emanation of the intellect: and the person Who proceeds in God, by way of emanation of the intellect, is called the Son\" (a.2).</p>
<p><strong>Implies relation to creatures (a.3).</strong> God, knowing himself, knows every creature. The word conceived in the mind represents everything actually understood. So the Father, in uttering himself, utters every creature in the one Word. \"All things were made by him\" (John 1:3). The Word is the divine 'art' in which creation is conceived: \"In Him was life\"; and the Word is \"the image of the invisible God, the firstborn of every creature\" (Col 1:15).</p>
${RC("t3l7",`<p>Recall the <strong>divine ideas</strong> (q.15, T3 L7): the patterns of all creatures in God's mind. Thomas now locates them, as it were, in the Word: God's one act of self-knowledge expresses itself in the Son and in him contains every creature's exemplar. Creation is 'through the Word'.</p>`)}
<div class="co apply"><div class="co-h">Apply · reading John's Prologue</div><p>Open the Reader at John 1. Thomas's lecture divides the Prologue by these same questions: the Word's existence (v.1a), distinction from the Father (v.1b), divinity (v.1c), co-eternity (v.2), and creative power (v.3). The Golden Chain commentary there quotes Augustine on the inner word.</p></div>`,
  check:Q("Why does 'Word' imply relation to creatures (q.34 a.3)?",[["Because the Word is a creature","No."],["Because in knowing himself God knows all creatures, and his Word expresses all he knows","Correct."],["Because creatures produce the Word","No."]],1)},
 {id:"s4",h:"4. Image: the Son alone, and man 'to the image' (q.35; q.93)",html:`<p><strong>What an image is (q.35 a.1).</strong> Not any likeness suffices. An image must be like in species (or in a sign of species, as shape for bodies), and must <em>come from</em> what it resembles. A son is the image of his father; an egg is like another egg but not its image.</p>
<p><strong>Proper to the Son (a.2).</strong> The Greek Fathers sometimes called the Spirit the Image of the Son; the Latins reserve the name for the Son, as Scripture does: \"Who is the image of the invisible God\" (Col 1:15); \"the brightness of his glory and the figure of his substance\" (Heb 1:3). Thomas's reason: the Son proceeds as Word, whose very nature is to be a likeness of its source; the Spirit proceeds as Love, which is not a likeness of its source as such.</p>
<p><strong>Man to the image (q.93).</strong> Man is made <em>to</em> (<em>ad</em>) the image of God: an imperfect image, in his intellectual nature. And since the image of the Trinity is found where something proceeds as word and love, man images the Trinity most of all when his mind knows and loves God himself (q.93 aa.6–8).</p>
${RC("f5",`<p>F5: intellect and will are the powers that make man a person, able to know truth and love the good. q.93 adds: these powers are made for God. The image is fullest not when the mind knows anything at all, but when it knows and loves its Creator.</p>`)}
<div class="co bridge"><div class="co-h">Psychology</div><p>Psychology measures cognition and motivation separately. Thomas's image-doctrine says they belong together and have a direction: understanding that issues in love, and love that rests in truth. This is a normative claim, not an empirical one, but it gives a frame for therapy goals: integration of what one knows and what one wants (P1, P8).</p></div>`,
  check:Q("What, besides likeness, does an image require?",[["Being visible","No."],["Origin from what it resembles","Correct: q.35 a.1."],["Being made of the same matter","No."]],1)},
 {id:"s5",h:"5. The analogy weighed",html:`<p>Thomas calls the psychological analogy fitting, not demonstrative (q.32 a.1 ad 2; T4 L1). Its strengths and limits:</p>
<div class="tablewrap"><table class="t"><thead><tr><th>Strengths</th><th>Limits</th></tr></thead><tbody>
<tr><td>Shows how procession can be wholly internal, answering Arius</td><td>In us, the word and love are accidents; in God, they are subsistent persons</td></tr>
<tr><td>Explains why there are two processions, and why only the first is generation</td><td>A human mind is one person; the analogy can tilt toward modalism if pressed</td></tr>
<tr><td>Grounds the order: love follows knowledge (the Filioque)</td><td>Our concepts are many and successive; the Word is one and eternal</td></tr>
<tr><td>Connects the Trinity with the image of God in man</td><td>It starts from one person's psychology, not from relations between persons</td></tr></tbody></table></div>
<p><strong>The social alternative.</strong> Richard of St Victor (d.1173) argued from love between persons: perfect love requires another to love (the Son) and a third to share that love (the Spirit). Some modern theologians prefer such 'social' models. Thomas uses Richard's argument as confirming, not proving (q.32 a.1 obj 2 and ad 2). The two analogies are complementary; Catholic teaching does not canonise either.</p>
${RC("t3l2",`<p>Why must the analogy 'limp'? Because of <strong>simplicity</strong> (T3 L2): God has no accidents. Whatever in us is a quality added to a substance (knowledge, love) in God is identical with his being. So in God the Word is not something the Father <em>has</em>; it is someone.</p>`)}`,
  check:Q("What is the main limit of the psychological analogy?",[["It denies the Son's divinity","No."],["In us, word and love are accidents; in God they are subsistent persons","Correct."],["It was never used by Thomas","He uses it constantly."]],1)}
 ],
 quiz:[
  Q("For Thomas, 'word' first and chiefly means…",[["the spoken sound","Secondary."],["the interior concept of the mind","Correct: q.34 a.1."],["the imagined sound","Third sense."],["a written sign","No."]],1,"ST I q.34 a.1",{bloom:"Remember",terms:["verbum-mentis"],diff:1}),
  Q("Generation in the strict sense is…",[["any change from non-being to being","That is the common sense."],["the origin of a living being from a conjoined living principle by way of likeness in nature","Correct: q.27 a.2."],["creation","No."],["procession of love","No."]],1,"ST I q.27 a.2",{bloom:"Remember",terms:["procession"],diff:2}),
  Q("Which immanent act is in us but not in God?",[["Understanding","In God."],["Willing","In God."],["Sensing","Correct: q.27 a.5."],["Loving","In God."]],2,"ST I q.27 a.5",{bloom:"Remember",terms:[],diff:1}),
  Q("Why does the procession of Love presuppose the procession of the Word?",[["Because the Spirit is younger","No."],["Because nothing is loved unless first known","Correct."],["Because the Son created the Spirit","No."],["By convention","No."]],1,"ST I q.27 a.3 ad 3; q.36 a.2",{bloom:"Understand",terms:["procession"],diff:2}),
  Q("'Word' is a personal name because…",[["it signifies something proceeding from another","Correct: q.34 a.1."],["it is used in John 1","True but not the reason."],["all three persons are words","No."],["it signifies the essence","It does not."]],0,"ST I q.34 a.1",{bloom:"Understand",terms:["verbum-mentis"],diff:2}),
  Q("Which text calls the Son 'the image of the invisible God'?",[["John 1:1","No."],["Colossians 1:15","Correct."],["Hebrews 1:3","It says 'figure of his substance'."],["Genesis 1:26","That concerns man."]],1,"Col 1:15",{bloom:"Remember",terms:["image-dei"],diff:1}),
  Q("Why do the Latins not call the Spirit 'Image'?",[["Because he is not divine","No."],["Because he proceeds as Love, not by way of likeness","Correct: q.35 a.2."],["Because he has no relation to the Son","He does."],["Because the Greeks forbade it","No."]],1,"ST I q.35 a.2",{bloom:"Analyse",terms:["image-dei"],diff:3}),
  Q("Man images the Trinity most fully when…",[["he is born","No."],["his mind knows and loves God","Correct: q.93 aa.7–8."],["he forms any concept","Less fully."],["he has children","Not Thomas's point here."]],1,"ST I q.93",{bloom:"Understand",terms:["image-dei"],diff:2}),
  Q("Richard of St Victor argued for the Trinity from…",[["mind and its word","That is Augustine."],["perfect love requiring a beloved and a co-beloved","Correct."],["the Five Ways","No."],["Scripture alone","No."]],1,"q.32 a.1 obj 2",{bloom:"Remember",terms:[],diff:2}),
  Q("Thomas regards arguments like Augustine's and Richard's as…",[["proofs","No."],["confirmations showing fittingness once the faith is held","Correct: q.32 a.1 ad 2."],["heretical","No."],["useless","No."]],1,"ST I q.32 a.1",{bloom:"Evaluate",terms:["psych-analogy"],diff:2})
 ],
 construct:{q:"Whether 'Word' is the Son's proper name?",ref:"ST I q.34 a.2",
  model:{obj:"It seems not: the Son is a subsisting person, but a word does not subsist; further, the word is the expression of the speaker, but all three persons can be said to express, so 'Word' is not proper to one.",sc:"\"In the beginning was the Word… and the Word was made flesh\" (John 1:1, 14); and Augustine: \"By Word we understand the Son alone.\"",resp:"'Word', taken properly, signifies an emanation of the intellect. The person who proceeds in God by way of emanation of the intellect is called the Son, and that procession is called generation. So 'Word' is the proper name of the Son.",rep:"In us the word is an accident, not subsisting; but in God, where to be and to understand are the same, the Word is subsistent. To speak, properly, is to utter a word; so only the Father speaks the Word, though all three understand."},
  rubric:["Objection argues that a word does not subsist, or that all three 'speak'.","Sed contra quotes John 1 or Augustine.","Respondeo: Word = emanation of intellect = Son by generation.","Reply 1 uses simplicity: in God the Word subsists.","Reply 2 distinguishes speaking (uttering the Word) from understanding."]},
 drill:{title:"Order Thomas's argument for two processions",parts:["Procession in God follows an action remaining in the agent","An intellectual nature has two such actions: understanding and willing","Understanding produces a word, by way of likeness: generation of the Son","Willing produces an impulse of love, not a likeness: procession of the Spirit","Love presupposes knowledge, so the second procession presupposes the first"]},
 connections:`<p><strong>Back.</strong> F5 (intellect, will, concept), T3 L7–L8 (knowledge and will in God), T3 L2 (simplicity), T4 L1–L2.</p><p><strong>Forward.</strong> L5 (the Spirit as Love, and the Filioque, rest on this lesson). T5 and the treatise on man (q.93) apply the image. T11: the Word made flesh, and why it is fitting that the Son, not the Father or Spirit, became incarnate (III q.3 a.8).</p><p><strong>Reader.</strong> John 1:1–18 with Thomas's lectures and the Catena aurea.</p>`},

// ===================== L4 PERSON AND THE GRAMMAR OF THE TRINITY =====================
{id:"t4l4",ord:4,code:"T4 · Lesson 4",title:"Relation and person: the grammar of the Trinity (qq.28–32, 39–41)",
 outcomes:["Explain how relations in God can be real, identical with the essence, and yet really distinct from one another (q.28).","Defend Boethius's definition of person, explain 'hypostasis', and show why a divine person is a subsisting relation (q.29).","Explain what numbers mean in God and why there are exactly three persons (q.30).","Apply Thomas's rules of Trinitarian speech (q.31; q.39): distinct, not diverse; other (alius), not another thing (aliud).","Name the five notions and the notional acts, and explain why the essence neither begets nor is begotten (qq.32, 39, 41)."],
 prereq:["relation-divine","person","hypostasis","notion","notional-act","suppositum","simplicity"],
 recall:[
  ["f4","What is a relation in Aristotle's categories, and why is it unusual?","An accident whose whole being is 'toward another' (ad aliquid). Unlike quantity or quality, it does not as such add anything intrinsic; some relations are real, others exist only in the mind."],
  ["t3l2","What is a suppositum, and how does God's differ from a creature's?","The concrete subsisting individual of a nature. In creatures the suppositum differs from its nature (Socrates has humanity); in God nature and suppositum are identical (q.3 a.3)."],
  ["t4","What are the four real relations in God?","Paternity, filiation, active spiration, passive spiration (procession)."],
  ["t4l2","What did the Cappadocians mean by ousia and hypostasis?","Ousia: the one essence common to the three. Hypostasis: each distinct concrete subsistent (Father, Son, Spirit)."]],
 reading:{primary:[["ST I q.28 aa.1–4 (relations)",NA("1028.htm")],["ST I q.29 aa.1–4 (person)",NA("1029.htm")],["ST I q.30 aa.1–4 (plurality of persons)",NA("1030.htm")],["ST I q.31 aa.1–4 (unity and plurality: rules of speech)",NA("1031.htm")],["ST I q.32 aa.2–4 (notions)",NA("1032.htm")],["ST I q.39 aa.1–6 (persons and essence)",NA("1039.htm")]],
  secondary:["Emery, G. (2007) The Trinitarian Theology of Saint Thomas Aquinas, chs 5–6.","Boethius, Contra Eutychen et Nestorium, ch. 3 (the definition of person).","Ratzinger, J. (1990) 'Concerning the notion of person in theology', Communio, 17(3), pp. 439–454.","Sokolowski, R. (2006) Christian Faith and Human Understanding. Washington, DC: CUA Press, ch. 10."]},
 scripture:[["John 10:30, I and the Father are one (unum, neuter)",null],["John 14:9–10, he that seeth me seeth the Father also",null],["John 5:19, the Son cannot do any thing of himself","j5-19"]],
 sections:[
 {id:"s1",h:"1. Real relations, identical with the essence (q.28 aa.1–2)",html:`<p>Relation is the strangest of the categories. Every other genus (quantity, quality) has being <em>in</em> its subject. Relation, as relation, is only <em>toward</em> another. That is why some relations exist only in thought (left and right, the same as itself) while others are real (father to son).</p>
<p><strong>Real in God (a.1).</strong> When something proceeds from a principle of the same nature, both are really related. The processions in God are real and within one nature, so the relations are real.</p>
<p><strong>Identical with the essence (a.2).</strong> In creatures a relation has two aspects: its being-in (as an accident in a subject) and its being-toward. In God nothing is accidental, so the being-in of a relation is the divine essence itself. Thomas mentions Gilbert de la Porrée, who made the relations 'assistant' or externally attached, and later retracted at the Council of Rheims (1148).</p>
<div class="quote">"Relation really existing in God is really the same as His essence and only differs in its mode of intelligibility."<span class="src">ST I q.28 a.2 · Dominican tr. (1920)</span></div>
${RC("f4",`<p>F4 listed relation among the nine <strong>accidents</strong>. Here Thomas exploits what is special about it: its 'toward-another' aspect does not require it to be an accident. In God, all the being-in is essence; only the being-toward remains to distinguish.</p>`)}`,
  check:Q("What did Gilbert de la Porrée hold about the divine relations?",[["That they are identical with the essence","That is Thomas's view."],["That they are 'assistant', externally attached","Correct: q.28 a.2."],["That there are none","No."]],1)},
 {id:"s2",h:"2. Really distinct from one another; person as subsisting relation (q.28 a.3; q.29)",html:`<p><strong>Really distinct (q.28 a.3).</strong> \"The very nature of relative opposition includes distinction.\" A father is not his own son. So opposed relations in God are really distinct from each other, though each is identical with the one essence.</p>
<div class="co core"><div class="co-h">The apparent paradox</div><p>A = C and B = C, so A = B? That rule holds for things identical in every respect. Paternity is identical with the essence <em>as to being</em>, but not <em>as to its meaning</em> (toward the Son). Since what distinguishes is precisely the 'toward', Father and Son are really distinct while one in essence (q.28 a.3 ad 1).</p></div>
<p><strong>Person (q.29 a.1).</strong> Boethius: \"a person is an individual substance of a rational nature.\" Thomas defends it: individuals have a special name in the genus of substance (hypostases); and among them, rational individuals, \"which have dominion over their own actions\", deserve a still more special name: person.</p>
<p><strong>Said of God (a.3).</strong> \"'Person' signifies what is most perfect in all nature—that is, a subsistent individual of a rational nature.\" So it is said of God, eminently.</p>
<p><strong>Signifies relation (a.4).</strong> In God, what is distinct and subsistent is the relation, which subsists because it is the essence. So: \"a divine person signifies a relation as subsisting\", signifying \"relation directly, and the essence indirectly\".</p>
${RC("t4l2",`<p>Compare the Cappadocian <strong>hypostasis</strong> (L2). Thomas: 'hypostasis' names the individual substance; 'person' adds rational nature (q.29 a.2). In God both are the subsisting relation.</p>`)}`,
  check:Q("According to q.29 a.4, 'person' in God signifies…",[["the essence directly, the relation indirectly","Reversed."],["the relation directly, the essence indirectly","Correct."],["neither","No."]],1)},
 {id:"s3",h:"3. Why three, and what numbers mean (q.30)",html:`<p><strong>Several persons (a.1).</strong> Person signifies subsisting relation; there are several real relations; so there are several persons.</p>
<p><strong>Exactly three (a.2).</strong> \"A real distinction between the divine relations can come only from relative opposition.\" Paternity and filiation are opposed; so are active spiration and procession. But active spiration is not opposed to paternity or filiation, so it belongs to both Father and Son and makes no new person. So: three persons, four relations, five notions.</p>
${RC("t4",`<p>L1 gave this argument in brief. Here it is in its home question. Try to state it from memory: what is opposed to what?</p>`)}
<p><strong>What 'three' means (a.3).</strong> Numbers in God do not posit quantity. 'One' signifies undivided being; 'many' signifies beings each undivided and distinct from the others. So numeral terms in God signify the things of which they are said and add only negation: 'three persons' means Father, Son and Spirit, each undivided in himself and not the others.</p>
${RC("t3l5",`<p>This is the <strong>transcendental one</strong> from T3 L5 (q.11 a.1): one adds to being only a negation of division. q.30 a.3 applies it: plurality in God is not a quantity but the negation of identity among the relations.</p>`)}
<p><strong>'Person' common to the three (a.4)</strong>: not as a common nature, like 'man' in three men, but by a community of reason, as 'someone' is common.</p>`,
  check:Q("Numeral terms in God, like 'three', signify…",[["a quantity in God","God has no quantity."],["the persons themselves, adding only negation (each undivided, not the others)","Correct: q.30 a.3."],["three essences","No."]],1)},
 {id:"s4",h:"4. Rules of speech: how to talk about the Trinity (q.31; q.39)",html:`<p>\"A heresy arises from words wrongly used\" (Jerome, quoted in q.31 a.2). Thomas steers between Arius (three substances) and Sabellius (one person):</p>
<div class="tablewrap"><table class="t"><thead><tr><th>Say</th><th>Avoid</th><th>Why</th></tr></thead><tbody>
<tr><td>Distinction</td><td>Diversity, difference</td><td>Would divide the essence (Arius)</td></tr>
<tr><td>Other (alius: another someone)</td><td>Another thing (aliud)</td><td>The Son is another person, not another being</td></tr>
<tr><td>Unity, one God</td><td>Singularity, 'only' God (unicus) of the Father</td><td>Would remove plurality of persons (Sabellius)</td></tr>
<tr><td>Three persons</td><td>Separation, division, parts</td><td>God has no parts</td></tr>
<tr><td>Equal, similar</td><td>Disparity, alien, discrepant</td><td>No inequality or unlikeness in God</td></tr></tbody></table></div>
<p><strong>Essence and person (q.39).</strong> In God, essence and person are really the same (a.1), so we can say 'three persons of one essence' (a.2). But not every sentence is allowed:</p>
<ul><li>✓ \"God begets God\": 'God' (concrete) can stand for the person of the Father (a.4).</li>
<li>✗ \"The essence begets the essence\": 'essence' (abstract) stands only for the essence, which is common and does not beget (a.5). This was Joachim of Fiore's error, condemned at Lateran IV.</li>
<li>✓ \"Three persons are one God\"; ✗ \"Three Gods\": substantive essential names are said in the singular (a.3).</li></ul>
${RC("t3l6",`<p>This is T3 L6's distinction between the <strong>thing signified</strong> and the <strong>mode of signifying</strong>, applied to grammar. 'God' signifies the divine nature in the mode of one who has it, so it can stand for a person; 'Godhead' or 'essence' signifies it abstractly, so it cannot.</p>`)}`,
  check:Q("Why can we say 'God begets God' but not 'essence begets essence'?",[["Because 'God' signifies in the mode of one who has the nature, and can stand for a person; 'essence' cannot","Correct: q.39 aa.4–5."],["Because the Father is not God","No."],["Because the essence is created","No."]],0)},
 {id:"s5",h:"5. Notions and notional acts (qq.32, 40–41)",html:`<p><strong>Notions (q.32 a.3).</strong> \"A notion is the proper idea whereby we know a divine Person.\" There are five:</p>
<div class="tablewrap"><table class="t"><thead><tr><th>Notion</th><th>Belongs to</th><th>Is it a relation?</th><th>Is it a personal property?</th></tr></thead><tbody>
<tr><td>Innascibility (being unbegotten)</td><td>Father</td><td>No: a negation</td><td>Yes (a mark of the Father)</td></tr>
<tr><td>Paternity</td><td>Father</td><td>Yes</td><td>Yes</td></tr>
<tr><td>Filiation</td><td>Son</td><td>Yes</td><td>Yes</td></tr>
<tr><td>Common (active) spiration</td><td>Father and Son</td><td>Yes</td><td>No: common to two</td></tr>
<tr><td>Procession (passive spiration)</td><td>Holy Spirit</td><td>Yes</td><td>Yes</td></tr></tbody></table></div>
<p>So: one essence, two processions, three persons, four relations, five notions. Thomas notes that on notions theologians may hold different opinions without heresy, as long as nothing follows against faith (q.32 a.4).</p>
<p><strong>Relations constitute the persons (q.40).</strong> The relations do not merely manifest persons already distinct; they constitute them (a.2). Abstract the relations in thought and no hypostases remain, only the essence (a.3).</p>
<p><strong>Notional acts (q.41).</strong> To signify the order of origin we attribute acts to persons: begetting, being begotten, spirating, proceeding. These are not voluntary in the sense of chosen (the Father does not 'decide' to beget), nor forced; they are natural (a.2). The Son is begotten \"from the Father's substance\", not from nothing (a.3).</p>
<div class="co check"><div class="co-h">Memory aid</div><p><strong>1-2-3-4-5</strong>: one essence, two processions, three persons, four relations, five notions.</p></div>`,
  check:Q("Which notion is NOT a relation?",[["Paternity","It is a relation."],["Innascibility","Correct: it is a negation, being unbegotten."],["Filiation","It is a relation."]],1)}
 ],
 quiz:[
  Q("A relation in God is really identical with…",[["the other relations","No: opposed relations are really distinct."],["the divine essence","Correct: q.28 a.2."],["a creature","No."],["nothing","No."]],1,"ST I q.28 a.2",{bloom:"Remember",terms:["relation-divine"],diff:1}),
  Q("Opposed relations are really distinct because…",[["they are different substances","No."],["relative opposition includes distinction","Correct: q.28 a.3."],["they are accidents","No accidents in God."],["they belong to different natures","One nature."]],1,"ST I q.28 a.3",{bloom:"Understand",terms:["relation-divine"],diff:2}),
  Q("Boethius defined person as…",[["a relation as subsisting","That is Thomas's account for God."],["an individual substance of a rational nature","Correct."],["a mask","Etymology, not definition."],["a mode of being","Modalism."]],1,"ST I q.29 a.1",{bloom:"Remember",terms:["person"],diff:1}),
  Q("'Person' is said of God because it signifies…",[["something limited","No."],["what is most perfect in all nature","Correct: q.29 a.3."],["a body","No."],["three gods","No."]],1,"ST I q.29 a.3",{bloom:"Understand",terms:["person"],diff:1}),
  Q("Why does active spiration not make a fourth person?",[["It is not real","It is real."],["It is not opposed to paternity or filiation","Correct: q.30 a.2."],["It belongs to the Spirit","It belongs to Father and Son."],["It is a notion only","It is a real relation."]],1,"ST I q.30 a.2",{bloom:"Analyse",terms:["notion"],diff:2}),
  Q("We may say the Son is 'other' (alius) than the Father but not…",[["another person","He is another person."],["another thing (aliud)","Correct: q.31 a.2."],["begotten","He is begotten."],["equal","He is equal."]],1,"ST I q.31 a.2",{bloom:"Apply",terms:["person"],diff:2}),
  Q("Which statement is correct?",[["The essence begets the essence","Joachim's error."],["God begets God","Correct: q.39 a.4."],["There are three Gods","No."],["The Father is the only God (unicus)","Avoided as Sabellian."]],1,"ST I q.39",{bloom:"Apply",terms:[],diff:2}),
  Q("How many notions are there?",[["Three","Persons."],["Four","Relations."],["Five","Correct: q.32 a.3."],["Two","Processions."]],2,"ST I q.32 a.3",{bloom:"Remember",terms:["notion"],diff:1}),
  Q("According to q.40, if the relations were abstracted from the persons in thought…",[["the hypostases would remain","Thomas denies this."],["no hypostases would remain, only the essence","Correct: q.40 a.3."],["four persons would remain","No."],["God would disappear","The essence remains."]],1,"ST I q.40 a.3",{bloom:"Analyse",terms:["relation-divine"],diff:3}),
  Q("The Father begets the Son…",[["by free choice, as he creates","No: generation is natural."],["by nature, not by a choice that could have been otherwise","Correct: q.41 a.2."],["from nothing","No: from his substance (a.3)."],["by compulsion","No."]],1,"ST I q.41 aa.2–3",{bloom:"Understand",terms:["notional-act"],diff:2})
 ],
 construct:{q:"Whether this word 'person' signifies relation?",ref:"ST I q.29 a.4",
  model:{obj:"It seems not: 'person' is said of each person in himself, absolutely ('the Father is a person'), whereas relative names refer to another; further, Augustine says 'person' is said of God absolutely.",sc:"Boethius says every word referring to the persons signifies relation; and 'person' belongs to the persons.",resp:"In God distinction is only by relations of origin. Relation in God is not an accident but the divine essence itself, and so it subsists. As 'this man' signifies this flesh and this soul, so 'divine person' signifies distinction by relation, subsisting. So 'person' in God signifies relation as subsisting: relation directly, and the essence indirectly; not relation as relation, but as hypostasis.",rep:"'Person' signifies relation not by way of relation (toward another) but by way of substance (subsisting); so it is said of each absolutely, while still signifying a relation."},
  rubric:["Objection: 'person' is said absolutely, not relatively.","Sed contra cites Boethius on relative names.","Respondeo: distinction in God only by relation; relation identical with essence, so subsisting.","Respondeo: 'relation directly, essence indirectly'.","Reply: relation signified by way of substance, not by way of relation."]},
 drill:{title:"Build the Trinitarian count",parts:["One essence","Two processions","Three persons","Four relations","Five notions"]},
 connections:`<p><strong>Back.</strong> F4 (relation as category), T3 L2 (simplicity; suppositum), T3 L5 (transcendental one), T3 L6 (mode of signifying), T4 L1–L2.</p><p><strong>Forward.</strong> L5 uses the logic of opposition to argue for the Filioque. T11 applies 'person' and 'nature' to Christ: one divine person, two natures, and the rules of speech become the communication of idioms.</p><p><strong>Psychology.</strong> The definition of person as an individual 'having dominion over its own actions' is the root of the clinical concept of agency and responsibility (P3 on imputability).</p>`},

// ===================== L5 THE HOLY SPIRIT; FILIOQUE =====================
{id:"t4l5",ord:5,code:"T4 · Lesson 5",title:"The Holy Spirit: Love, Gift and the Filioque (qq.36–38)",
 outcomes:["Explain why 'Holy Spirit' is a proper name and why the procession of love has no proper name of its own (q.36 a.1; q.27 a.4).","Give Thomas's argument from relative opposition that the Spirit proceeds from the Son (q.36 a.2).","Explain 'from the Father through the Son' and 'one principle' (q.36 aa.3–4), and the Church's teaching at Lyons II and Florence.","Summarise the Orthodox objection and the 1995 Vatican Clarification.","Explain why 'Love' and 'Gift' are proper names of the Spirit (qq.37–38)."],
 prereq:["filioque","gift","procession","relation-divine","psych-analogy","notion"],
 recall:[
  ["t4l4","Why can there be real distinction in God only by opposed relations?","Because everything absolute belongs to the one essence; so only relative opposition (principle / from-the-principle) distinguishes persons (q.28 a.3; q.30 a.2)."],
  ["t4l3","Why does the procession of Love presuppose that of the Word?","Because nothing is loved unless it is first known."],
  ["t3l8","How does God's love differ from ours?","Ours is caused by the good of its object; God's causes the good in its object (q.20 a.2)."],
  ["t4l2","What did Constantinople I (381) say of the Spirit?","The Lord and giver of life, who proceeds from the Father, who with the Father and the Son is worshipped and glorified."]],
 reading:{primary:[["ST I q.36 aa.1–4 (the Holy Spirit)",NA("1036.htm")],["ST I q.37 aa.1–2 (Love)",NA("1037.htm")],["ST I q.38 aa.1–2 (Gift)",NA("1038.htm")],["Council of Florence, Laetentur caeli (1439)",'https://www.papalencyclicals.net/councils/ecum17.htm'],["Pontifical Council for Promoting Christian Unity (1995) The Greek and Latin Traditions regarding the Procession of the Holy Spirit",'https://www.ewtn.com/catholicism/library/greek-and-latin-traditions-regarding-the-procession-of-the-holy-spirit-29259'],["CCC 243–248, 683–690",'https://www.vatican.va/archive/ENG0015/__P17.HTM']],
  secondary:["Siecienski, A.E. (2010) The Filioque: History of a Doctrinal Controversy. Oxford: Oxford University Press.","Congar, Y. (1983) I Believe in the Holy Spirit. 3 vols. London: Geoffrey Chapman, vol. 3.","Emery, G. (2007) The Trinitarian Theology of Saint Thomas Aquinas, chs 9–10.","Thomas Aquinas, Contra errores Graecorum (1263–64)."]},
 scripture:[["John 15:26, whom I will send you from the Father","j15-26"],["John 16:14–15, he shall receive of mine",null],["Galatians 4:6, the Spirit of his Son",null],["Romans 5:5, the charity of God is poured forth",null]],
 sections:[
 {id:"s1",h:"1. The name 'Holy Spirit' (q.36 a.1)",html:`<p>The second procession is less known to us than the first. We have a rich vocabulary for knowing (word, concept, idea) and a poor one for loving. So Thomas says the procession of love \"has no proper name of its own\", nor do the relations that follow from it; we call them 'spiration' and 'procession', words that name origin rather than relation.</p>
<p>So Scripture's name 'Holy Spirit' is fitting by usage and by meaning:</p>
<ul><li><strong>Spirit</strong> (spiritus, breath): love is an impulse, a moving breath; and Christ \"breathed on them; and he said to them: Receive ye the Holy Ghost\" (John 20:22).</li>
<li><strong>Holy</strong>: holiness is said of what is ordered to God; love is what orders us to him.</li></ul>
${RC("t4l3",`<p>L3: the Word proceeds 'by way of likeness', the Spirit 'by way of impulse'. 'Spirit' (breath, impulse) is therefore the right image for the second procession, as 'Word' and 'Image' are for the first.</p>`)}`,
  check:Q("Why, according to Thomas, has the procession of love no proper name of its own?",[["Because it is not real","It is real."],["Because our vocabulary for love is poorer than for knowledge","Correct: q.37 a.1; q.27 a.4 ad 3."],["Because Scripture forbids naming it","No."]],1)},
 {id:"s2",h:"2. From the Son: the argument from opposition (q.36 a.2)",html:`<p>Thomas's main argument is short and rigorous:</p>
<ol><li>The persons are distinguished only by relations (L4).</li>
<li>Relations distinguish only if they are opposed. The Father has two relations (to the Son and to the Spirit), but they are not opposed, so they make one person.</li>
<li>If the Son and the Spirit were each related only to the Father, their relations would not be opposed to each other. Then they would not be distinct persons: \"this is heretical since it destroys the Faith in the Trinity\".</li>
<li>So the Son and the Spirit must be related to each other by opposed relations of origin: either the Son from the Spirit (which no one says) or the Spirit from the Son.</li></ol>
<div class="quote">"It must be said that the Holy Ghost is from the Son. For if He were not from Him, He could in no wise be personally distinguished from Him."<span class="src">ST I q.36 a.2 · Dominican tr. (1920)</span></div>
<p><strong>The second argument</strong> uses the order of the processions: the Son proceeds as Word, the Spirit as Love, and love proceeds from the word, since we love only what we know.</p>
${RC("t4l4",`<p>This is L4's logic of <strong>relative opposition</strong> pressed to its conclusion. Notice that it presupposes the Latin understanding of relations as constitutive of persons (q.40). Orthodox theologians who locate the distinction differently do not accept the premise.</p>`)}
<p><strong>Scripture.</strong> The Spirit is \"the Spirit of his Son\" (Gal 4:6). The Son sends the Spirit (John 15:26), and \"he shall receive of mine… All things whatsoever the Father hath are mine\" (John 16:14–15): if the Son has all the Father has except paternity, he has also being the principle of the Spirit.</p>`,
  check:Q("Thomas argues that without the Filioque the Son and Spirit would not be distinct because…",[["they would both be begotten","No."],["their only relations would be to the Father, and these are not opposed to each other","Correct: q.36 a.2."],["the Father would be the Spirit","No."]],1)},
 {id:"s3",h:"3. 'Through the Son' and 'one principle' (q.36 aa.3–4)",html:`<p><strong>Through the Son (a.3).</strong> Greek Fathers (Gregory of Nyssa, Maximus, John Damascene) said the Spirit proceeds 'from the Father through the Son'. Thomas accepts this: the preposition 'through' can name a cause that has its causality from another: we say \"the king works through the bailiff\", because the bailiff has from the king the power by which the effect proceeds. \"Because the Son receives from the Father that the Holy Ghost proceeds from Him, it can be said that the Father spirates the Holy Ghost through the Son.\"</p>
<p><strong>One principle (a.4).</strong> The Father and Son are one in everything where there is no opposition of relation. As principle of the Spirit they are not opposed. So they are one principle of the Spirit, by one spiration. Not two sources.</p>
<div class="co def"><div class="co-h">Magisterium</div><p><span class="voice">Magisterium</span>Lyons II (1274): the Spirit proceeds eternally from the Father and the Son, \"not as from two principles, but as from one principle; not by two spirations, but by one single spiration\" (DS 850). Florence (<em>Laetentur caeli</em>, 1439): the Greek 'through the Son' expresses that the Son, like the Father, is cause (Greek) or principle (Latin) of the Spirit's subsistence; and the Father gives the Son, in begetting him, everything except being Father, including being principle of the Spirit (DS 1300–1302; CCC 246–248).</p></div>
${RC("t4",`<p>Florence's other famous line, which you met in L1, belongs here: "In God all is one where there is no opposition of relation" (Decree for the Jacobites, 1442, DS 1330; CCC 255). That principle is exactly Thomas's argument in a.4.</p>`)}`,
  check:Q("Why are the Father and the Son one principle of the Spirit?",[["Because they are one person","They are two persons."],["Because as principle of the Spirit they are not opposed, and all is one where there is no opposition","Correct: q.36 a.4."],["Because the Son is the Father","No."]],1)},
 {id:"s4",h:"4. The ecumenical question",html:`<p><strong>History.</strong> The Creed of 381 says the Spirit proceeds \"from the Father\". The Latin 'and the Son' (<em>Filioque</em>) was added in Spain (Toledo III, 589), spread in the Frankish realm, and was sung at Rome under Benedict VIII (c.1014). Pope Leo III (809) affirmed the doctrine but refused to add it to the Creed, having the Creed engraved without it on silver shields at St Peter's.</p>
<p><strong>The Orthodox objections.</strong> (1) <em>Procedural</em>: Ephesus (431) forbade composing another creed; the West altered a conciliar text unilaterally. (2) <em>Theological</em> (Photius, 9th c.): the Father is the sole source (<em>monarchia</em>) of the Godhead; the Filioque seems to make two sources, or to confuse the Son with the Father.</p>
<p><strong>The 1995 Clarification</strong> of the Pontifical Council for Promoting Christian Unity proposed a reconciliation:</p>
<ul><li>The Father is the sole source (<em>aitia</em>) of the Son and the Spirit; the Catholic Church accepts this.</li>
<li>The Greek <em>ekporeusis</em> (in the Creed) means procession from the ultimate source, and so is said of the Father alone. The Latin <em>processio</em> is a wider word, meaning communication of the divine being, and can include the Son's role.</li>
<li>So the Latin Filioque does not deny the Father's monarchy; the Greek 'from the Father through the Son' expresses the same faith.</li></ul>
<p>The Catholic Church uses the Creed without the Filioque in Greek in its liturgy (e.g. Byzantine Catholics; Dominus Iesus 1, 2000, quotes the Creed of 381 without it).</p>
${RC("t4l2",`<p>Thomas himself answered the procedural objection (q.36 a.2 ad 2): each council expands the creed against a new error, so the Filioque is not a new creed but an explanation of what was implicit. Compare how Constantinople expanded Nicaea in L2.</p>`)}
<div class="co bridge"><div class="co-h">Contested</div><p>Orthodox theologians remain divided on whether the 1995 text resolves the theological issue; some accept 'through the Son' but not 'one principle'. The question is open in dialogue (Siecienski, 2010).</p></div>`,
  check:Q("According to the 1995 Clarification, the Greek ekporeusis signifies…",[["any communication of the divine being","That is the Latin processio."],["procession from the ultimate source, said of the Father alone","Correct."],["creation","No."]],1)},
 {id:"s5",h:"5. Love and Gift: the Spirit's proper names (qq.37–38)",html:`<p><strong>Love (q.37 a.1).</strong> 'Love' can be said of God essentially (God loves, all three) or personally. Personally, it is the proper name of the Spirit, as 'Word' is of the Son. When we love something, there results in the lover \"a certain impression… of the thing loved\", so that the beloved is in the lover as the known is in the knower. In God, this proceeding Love is a person.</p>
<p><strong>The Father and Son love each other by the Spirit (a.2).</strong> Not as if the Spirit caused their love, but as a tree flowers by its flowers: the Spirit is the Love proceeding from their mutual love.</p>
<p><strong>Gift (q.38 a.2).</strong> A gift properly is \"an unreturnable giving\", given without expecting return; its reason is love. \"So what we first give him is the love whereby we wish him well. Hence it is manifest that love has the nature of a first gift, through which all free gifts are given.\" So the Spirit, proceeding as Love, is the first Gift. Augustine: \"By the gift, which is the Holy Ghost, many particular gifts are portioned out to the members of Christ.\"</p>
${RC("t3l8",`<p>T3 L8: God's love <strong>creates the good it loves</strong>. Now we see its personal face: the Spirit is the Love in which God gives himself, and through whom every other gift is given. "The charity of God is poured forth in our hearts, by the Holy Ghost who is given to us" (Rom 5:5).</p>`)}
${RC("t7",`<p>T7: <strong>charity</strong> is the created gift by which we love God. Thomas's question (II-II q.23 a.2): is charity the Holy Spirit himself (Peter Lombard) or a created habit? Thomas: a created habit, produced by the Spirit who is uncreated Love. This lesson grounds that distinction.</p>`)}`,
  check:Q("Why is the Holy Spirit called the 'first Gift'?",[["Because he was given first in time","Not the reason."],["Because love is the first gift through which all free gifts are given, and he proceeds as Love","Correct: q.38 a.2."],["Because the Father gave him to the Son","Not the reason."]],1)}
 ],
 quiz:[
  Q("'Spirit' is a fitting name for the second procession because…",[["the Spirit is a wind","Metaphor only."],["love is an impulse, a moving breath","Correct."],["the Spirit has no body","True of all three."],["it is shorter","No."]],1,"ST I q.36 a.1",{bloom:"Understand",terms:[],diff:1}),
  Q("Thomas's main argument for the Filioque rests on…",[["the Creed of 381","It does not include the Filioque."],["relative opposition as the only principle of distinction","Correct: q.36 a.2."],["the authority of Charlemagne","No."],["the psychological analogy alone","That is the second argument."]],1,"ST I q.36 a.2",{bloom:"Understand",terms:["filioque","relation-divine"],diff:2}),
  Q("'The king works through the bailiff' illustrates…",[["two principles of the Spirit","No."],["how the Father spirates through the Son, from whom the Son has it","Correct: q.36 a.3."],["the Father being sent","No."],["modalism","No."]],1,"ST I q.36 a.3",{bloom:"Apply",terms:["filioque"],diff:2}),
  Q("Lyons II taught that the Spirit proceeds…",[["from two principles","Explicitly denied."],["from Father and Son as from one principle, by one spiration","Correct: DS 850."],["from the Father alone, excluding the Son","No."],["from the Son alone","No."]],1,"DS 850",{bloom:"Remember",terms:["filioque"],diff:2}),
  Q("Where was the Filioque first added to the Creed?",[["Rome, 381","No."],["Spain, Toledo III (589)","Correct."],["Constantinople, 869","No."],["Florence, 1439","No."]],1,"Toledo III",{bloom:"Remember",terms:["filioque"],diff:2}),
  Q("Which pope affirmed the doctrine but refused to add the Filioque to the Creed?",[["Leo III (809)","Correct."],["Gregory the Great","No."],["Benedict VIII","He allowed it to be sung."],["Pius IX","No."]],0,"Leo III",{bloom:"Remember",terms:[],diff:3}),
  Q("The 1995 Clarification affirms that the Father is…",[["one of two sources of the Spirit","No."],["the sole source (aitia) of Son and Spirit","Correct."],["less than the Son","No."],["the Spirit","No."]],1,"PCPCU 1995",{bloom:"Remember",terms:["filioque"],diff:2}),
  Q("'The Father and the Son love each other by the Holy Spirit' means…",[["the Spirit causes their love","Not as cause."],["the Spirit is the Love proceeding from their mutual love, as a tree flowers by its flowers","Correct: q.37 a.2."],["they need the Spirit to love","No."],["the Spirit is a creature","No."]],1,"ST I q.37 a.2",{bloom:"Analyse",terms:[],diff:3}),
  Q("A gift, properly, is…",[["anything handed over","Too broad."],["an unreturnable giving, whose reason is love","Correct: q.38 a.2."],["a payment","No."],["a loan","No."]],1,"ST I q.38 a.2",{bloom:"Remember",terms:["gift"],diff:1}),
  Q("Thomas held that charity in the soul is…",[["the Holy Spirit himself","That was Lombard's view."],["a created habit produced by the Spirit","Correct: II-II q.23 a.2."],["a passion","No."],["natural","No."]],1,"II-II q.23 a.2",{bloom:"Understand",terms:["charity"],diff:3})
 ],
 construct:{q:"Whether the Holy Ghost proceeds from the Son?",ref:"ST I q.36 a.2",
  model:{obj:"It seems not: Dionysius says we must not dare to say anything of God not expressed in Scripture, and Scripture says the Spirit proceeds from the Father (John 15:26), not from the Son; further, the Creed of Constantinople says only 'from the Father'.",sc:"Athanasius' Creed: \"The Holy Ghost is from the Father and the Son, not made, nor created, nor begotten, but proceeding.\"",resp:"The persons are distinguished only by opposed relations. If the Spirit were not from the Son, the Son and Spirit would be related only to the Father, by relations not opposed to each other; then they would not be distinct, which destroys the Trinity. So they must be related by opposed relations of origin; and since no one says the Son is from the Spirit, the Spirit is from the Son. This agrees with the order of the processions: love proceeds from the word.",rep:"Scripture says the Spirit is the Spirit of the Son and receives from him; this is equivalent. Councils expand earlier creeds against new errors without making a new creed."},
  rubric:["Objection cites John 15:26 or the Creed of 381.","Sed contra cites the Athanasian Creed or another authority.","Respondeo argues from relative opposition.","Respondeo adds the order of Word and Love.","Reply answers both the scriptural and the conciliar objections."]},
 drill:{title:"Order the history of the Filioque",parts:["Creed of Constantinople: 'from the Father' (381)","Toledo III adds 'and the Son' (589)","Leo III refuses to insert it at Rome (809)","Photius' objections (9th century)","Sung at Rome under Benedict VIII (c.1014)","Lyons II: one principle, one spiration (1274)","Florence: 'through the Son' reconciled (1439)","Vatican Clarification (1995)"]},
 connections:`<p><strong>Back.</strong> T4 L3 (procession of Love), L4 (opposed relations), T3 L8 (God's love), T4 L2 (the councils).</p><p><strong>Forward.</strong> L7: the Spirit's mission as Gift in the soul. T7: charity as created gift. T13: the Spirit in Confirmation and the epiclesis of the Mass. T14: the Spirit as soul of the Church (Mystici Corporis).</p><p><strong>Apologetics.</strong> The Filioque disputation in the Apologetics track uses this lesson.</p>`},

// ===================== L6 PERSONS COMPARED =====================
{id:"t4l6",ord:6,code:"T4 · Lesson 6",title:"The persons compared: equality, order, perichoresis, appropriation (qq.33, 39, 42)",
 outcomes:["Explain why the Father is principle without being cause, and why 'Father' is said first of God (q.33).","Show that the persons are equal in greatness, power and eternity, though there is an order of origin (q.42).","Explain the mutual indwelling of the persons (perichoresis) by essence, relation and origin (q.42 a.5).","Explain appropriation and give Thomas's appropriations from Hilary and Augustine (q.39 aa.7–8).","Apply these to Christian prayer and liturgy."],
 prereq:["appropriation","perichoresis","relation-divine","notion","person","eternity"],
 recall:[
  ["t4","What is appropriation?","Attributing to one person something common to all three, because it resembles what is proper to that person: power to the Father, wisdom to the Son, goodness to the Spirit (q.39 a.7)."],
  ["t4l4","Which five notions are there?","Innascibility, paternity, filiation, common spiration, procession."],
  ["t3l5","What is eternity, and why is God his own eternity?","The simultaneously-whole and perfect possession of interminable life; God is his own being, so he is his own duration (q.10 a.2)."],
  ["t3l3","What are the conditions of a likeness that is merely analogical?","When cause and effect are not in the same genus, the effect resembles the cause only by analogy, as being is common to all (q.4 a.3)."]],
 reading:{primary:[["ST I q.33 aa.1–4 (the Father)",NA("1033.htm")],["ST I q.39 aa.7–8 (appropriation)",NA("1039.htm")],["ST I q.42 aa.1–6 (equality and likeness)",NA("1042.htm")],["CCC 253–260",'https://www.vatican.va/archive/ENG0015/__P17.HTM']],
  secondary:["Emery, G. (2007) The Trinitarian Theology of Saint Thomas Aquinas, chs 8, 11.","Durand, E. (2005) La périchorèse des personnes divines. Paris: Cerf.","Ratzinger, J. (2000) The Spirit of the Liturgy. San Francisco: Ignatius, part 1.","Garrigou-Lagrange, R. (1952) The Trinity and God the Creator, chs on qq.39–42."]},
 scripture:[["John 14:10, I am in the Father and the Father in me",null],["Ephesians 2:18, by him we have access… in one Spirit to the Father",null],["Ephesians 3:14–15, the Father, of whom all paternity is named",null]],
 sections:[
 {id:"s1",h:"1. The Father: principle without principle (q.33)",html:`<p><strong>Principle, not cause (a.1).</strong> The Father is the principle of the Son, since the Son proceeds from him. The Greeks also say 'cause' (aitia); Latins prefer 'principle', because 'cause' suggests a difference of substance and dependence, as in creatures on God.</p>
<p><strong>'Father' said first of God (a.3).</strong> A name is said first of that in which its whole meaning is perfectly found. Fatherhood in creatures is partial: a human father gives a nature he received, at a moment, and not his whole being. The eternal Father gives the whole divine nature eternally. So fatherhood is first in God, and \"of whom all paternity in heaven and earth is named\" (Eph 3:15).</p>
${RC("t3l6",`<p>T3 L6 (q.13 a.6): as to the thing signified, names of pure perfections are said first of God. Thomas applies the same rule to a <em>personal</em> name. We learn 'father' from our fathers; but what the word means is fully realised only in God.</p>`)}
<p><strong>Unbegotten (a.4).</strong> \"The principle not from a principle, Who is the Father; and the principle from a principle, Who is the Son.\" Innascibility, a negation, is the Father's mark.</p>`,
  check:Q("Why is 'Father' said first of God, according to q.33 a.3?",[["Because Christians learn it first","That is the order of learning."],["Because its whole meaning, giving one's whole nature, is perfectly found only in God","Correct."],["Because God is male","Not the reason; God is not a body."]],1)},
 {id:"s2",h:"2. Equal, co-eternal, with an order of origin (q.42 aa.1–4, 6)",html:`<p><strong>Equality (a.1).</strong> Equality is the negation of greater and less. The Son has the same numerically one essence as the Father, so there can be no greater or less.</p>
<p><strong>Co-eternal (a.2).</strong> An effect may come after its cause because the agent acts by will at a chosen time, or because its action is successive. The Father begets by nature, not by a choice of time, and his action is not successive. So the Son is co-eternal: there never was when he was not.</p>
${RC("t4l2",`<p>This answers Arius' slogan from L2, "there was when he was not". Thomas's analysis: brightness exists as soon as the fire exists; so the Son, the "brightness of his glory" (Heb 1:3), is as eternal as the Father.</p>`)}
<p><strong>Order of nature (a.3).</strong> There is an order of origin, not of priority. One person is from another, but not after or less than another. Thomas calls it an \"order of nature\" only in the sense of origin, not as if one were prior by nature.</p>
<p><strong>Equal in greatness and power (aa.4, 6).</strong> The Son receives the whole perfection of the Father's nature, so he is equal in greatness; power follows nature, so he is equal in power. When Christ says \"The Father is greater than I\" (John 14:28), the Fathers read it of his humanity, or of the Father as source, not as greater in nature.</p>`,
  check:Q("Why is the Son co-eternal with the Father?",[["Because the Father chose an eternal moment","God does not choose times for generation."],["Because the Father begets by nature, with no successive action","Correct: q.42 a.2."],["Because the Son created time","Irrelevant."]],1)},
 {id:"s3",h:"3. Perichoresis: each in each (q.42 a.5)",html:`<p>\"Do you not believe that I am in the Father and the Father in me?\" (John 14:10). Thomas explains this mutual indwelling in three ways:</p>
<div class="tablewrap"><table class="t"><thead><tr><th>Ground</th><th>Explanation</th></tr></thead><tbody>
<tr><td>Essence</td><td>The Father is his essence and gives it wholly to the Son; so the Father is in the Son and the Son in the Father, \"God in God\" (Hilary)</td></tr>
<tr><td>Relation</td><td>Each of two relatives is in the concept of the other: one cannot think 'Father' without 'Son'</td></tr>
<tr><td>Origin</td><td>The procession is immanent: the Word does not leave the speaker; the Son remains in the Father</td></tr></tbody></table></div>
<p>The Greek word is <em>perichoresis</em> (John Damascene); the Latin <em>circumincessio</em>. It excludes both separation (tritheism) and confusion (modalism): each person is wholly in the others, without becoming the others.</p>
${RC("t4l3",`<p>The third ground is L3's <strong>inner word</strong>: what proceeds inwardly remains in its source. That is why the psychological analogy, for all its limits, illuminates perichoresis: my thought of the truth is 'in' me and I am 'in' it.</p>`)}`,
  check:Q("Which ground of perichoresis says one cannot think 'Father' without 'Son'?",[["Essence","No."],["Relation","Correct: q.42 a.5."],["Origin","No."]],1)},
 {id:"s4",h:"4. Appropriation (q.39 aa.7–8)",html:`<p>The persons are not known by reason. But essential attributes, which reason can know, can help manifest the persons, by a likeness to what is proper to each. \"For the manifestation of our faith it is fitting that the essential attributes should be appropriated to the persons\" (a.7).</p>
<p>Thomas organises the classical appropriations by four ways we consider any being (a.8):</p>
<div class="tablewrap"><table class="t"><thead><tr><th>We consider God…</th><th>Father</th><th>Son</th><th>Holy Spirit</th><th>Source</th></tr></thead><tbody>
<tr><td>as being</td><td>Eternity</td><td>Beauty (species)</td><td>Enjoyment (use)</td><td>Hilary</td></tr>
<tr><td>as one</td><td>Unity</td><td>Equality</td><td>Concord (connection)</td><td>Augustine</td></tr>
<tr><td>as having power to act</td><td>Power</td><td>Wisdom</td><td>Goodness</td><td>Augustine</td></tr>
<tr><td>in relation to effects</td><td>'Of whom' (ex quo)</td><td>'By whom' (per quem)</td><td>'In whom' (in quo)</td><td>Rom 11:36</td></tr></tbody></table></div>
<p>Why beauty to the Son? Because beauty has three conditions: integrity, proportion, clarity. The Son has the Father's nature whole (integrity), is his express Image (proportion), and is the Word, \"the light and splendor of the intellect\" (clarity).</p>
${RC("t3l3",`<p>Appropriation is a kind of <strong>analogy</strong> (T3 L3, L6): an essential perfection resembles a personal property. It never makes the perfection proper. All three are equally powerful, wise and good.</p>`)}`,
  check:Q("Which is appropriated to the Son?",[["Power","Father."],["Wisdom","Correct."],["Goodness","Spirit."]],1)},
 {id:"s5",h:"5. Living the doctrine: prayer and liturgy",html:`<p>The Church's prayer is Trinitarian in structure: \"by him [Christ] we have access both in one Spirit to the Father\" (Eph 2:18).</p>
<ul><li><strong>The collect</strong> is addressed to the Father, through the Son, in the unity of the Holy Spirit: '…through our Lord Jesus Christ, your Son, who lives and reigns with you in the unity of the Holy Spirit, one God, for ever and ever.'</li>
<li><strong>The Eucharistic Prayer</strong> is offered to the Father, recalls the Son's sacrifice, invokes the Spirit (epiclesis), and ends: 'Through him, and with him, and in him, O God, almighty Father, in the unity of the Holy Spirit, all glory and honour is yours.'</li>
<li><strong>The Sign of the Cross</strong>: one name, three persons (Matt 28:19).</li></ul>
${RC("t16a",`<p>From T16a: <strong>lex orandi, lex credendi</strong>. The doxology is the shortest summary of this lesson: equal glory (q.42), distinct persons (q.29), one God (q.11). Basil's argument from the liturgy (L2) works in both directions.</p>`)}
<div class="co apply"><div class="co-h">Apply · praying 'through' and 'in'</div><p>Appropriation shapes prayer without dividing God. We thank the Father as source, approach through the Son as mediator, and are moved in the Spirit as love. All three are worshipped together; the prepositions name the order of origin the persons have revealed.</p></div>
<div class="co bridge"><div class="co-h">Psychology · equality without sameness</div><p>The persons are perfectly equal and yet not interchangeable. This is a model that family systems and couple therapies seek in their own terms: differentiation (each a distinct self) together with closeness (Bowen's 'differentiation of self'; measured by the Differentiation of Self Inventory, Skowron &amp; Friedlander, 1998, <em>Journal of Counseling Psychology</em>, 45(3), pp. 235–246; correlational evidence links it to lower anxiety). The Trinity does not prove a therapy, but it offers a Christian image of the goal: unity that does not erase difference.</p></div>`,
  check:Q("The liturgical doxology 'Through him, and with him, and in him… in the unity of the Holy Spirit' expresses…",[["three gods","No."],["the order of origin among equal persons","Correct."],["modalism","No."]],1)}
 ],
 quiz:[
  Q("Latins prefer to call the Father 'principle' rather than 'cause' because…",[["'cause' suggests difference of substance and dependence","Correct: q.33 a.1 ad 1."],["the Father is not the Son's origin","He is."],["Greek is forbidden","No."],["'principle' is shorter","No."]],0,"ST I q.33 a.1",{bloom:"Understand",terms:[],diff:2}),
  Q("'Of whom all paternity in heaven and earth is named' is from…",[["John 1","No."],["Ephesians 3:15","Correct."],["Hebrews 1","No."],["Romans 8","No."]],1,"Eph 3:15",{bloom:"Remember",terms:[],diff:1}),
  Q("Equality in God is…",[["sameness of person","No."],["the negation of greater and less","Correct: q.42 a.1."],["a quantity","No."],["a relation of reason only","Not the point."]],1,"ST I q.42 a.1",{bloom:"Remember",terms:[],diff:1}),
  Q("'The Father is greater than I' (John 14:28) is read by the Fathers as referring to…",[["Christ's divine nature","No."],["his humanity, or the Father as source","Correct."],["a scribal error","No."],["the Spirit","No."]],1,"John 14:28",{bloom:"Apply",terms:[],diff:2}),
  Q("Perichoresis means…",[["the persons merge","No."],["each person is wholly in the others without confusion","Correct."],["three parts of God","No."],["the Father alone is God","No."]],1,"ST I q.42 a.5",{bloom:"Remember",terms:["perichoresis"],diff:1}),
  Q("Which is NOT a ground of perichoresis in q.42 a.5?",[["Essence","It is."],["Relation","It is."],["Origin","It is."],["Will","Correct."]],3,"ST I q.42 a.5",{bloom:"Understand",terms:["perichoresis"],diff:2}),
  Q("Beauty (species) is appropriated to…",[["the Father","Eternity."],["the Son","Correct: q.39 a.8."],["the Spirit","Enjoyment."],["none","No."]],1,"ST I q.39 a.8",{bloom:"Remember",terms:["appropriation"],diff:2}),
  Q("The three conditions of beauty are…",[["size, colour, use","No."],["integrity, proportion, clarity","Correct: q.39 a.8."],["truth, goodness, unity","Transcendentals."],["power, wisdom, goodness","Other appropriations."]],1,"ST I q.39 a.8",{bloom:"Remember",terms:[],diff:2}),
  Q("'In whom' (in quo) is appropriated to…",[["the Father","'Of whom'."],["the Son","'By whom'."],["the Holy Spirit","Correct."],["all equally, as proper","Appropriated, not proper."]],2,"ST I q.39 a.8; Rom 11:36",{bloom:"Remember",terms:["appropriation"],diff:2}),
  Q("The collect is addressed…",[["to the Spirit through the Father","No."],["to the Father, through the Son, in the unity of the Spirit","Correct."],["to Mary","No."],["to the Son alone always","No."]],1,"Roman Missal",{bloom:"Apply",terms:["liturgy"],diff:1})
 ],
 construct:{q:"Whether the Son is in the Father, and conversely?",ref:"ST I q.42 a.5",
  model:{obj:"It seems not: the Philosopher gives eight ways of one thing being in another, and none fits (not as part in whole, nor form in matter, nor thing in place); further, nothing is in what it comes from.",sc:"\"I am in the Father and the Father in me\" (John 14:10).",resp:"There are three considerations: essence, relation, origin. By essence, the Father is his essence and gives it to the Son, so each is in the other. By relation, each relative is in the concept of the other. By origin, the procession of the Word is immanent, so the Son remains in the Father.",rep:"The Son is in the Father in a way above all the ways found in creatures; most like the way a thing is in its principle when the principle shares its whole nature. What proceeds inwardly does not leave its source."},
  rubric:["Objection argues from Aristotle's ways of 'being in'.","Sed contra quotes John 14:10.","Respondeo gives all three grounds.","Each ground is correctly explained.","Reply notes that divine indwelling exceeds created modes."]},
 drill:{title:"Order the appropriations of Romans 11:36",parts:["Of him (ex ipso): the Father","By him (per ipsum): the Son","In him (in ipso): the Holy Spirit"]},
 connections:`<p><strong>Back.</strong> T3 L3, L5, L6 (analogy, eternity, names said first of God); T4 L2–L4.</p><p><strong>Forward.</strong> L7 (missions and indwelling). T16a (the Trinitarian shape of the Mass). T11: the Son's equality and the meaning of his 'obedience' in his human nature.</p><p><strong>Psychology.</strong> Section 5 on differentiation and closeness.</p>`},

// ===================== L7 MISSIONS AND INDWELLING =====================
{id:"t4l7",ord:7,code:"T4 · Lesson 7",title:"Sent into the world and into the soul: the missions and the indwelling (q.43)",
 outcomes:["Define mission and explain why it implies no change or inferiority in the one sent (q.43 aa.1–2).","Explain why the invisible mission takes place only by sanctifying grace, as a new presence of God known and loved (a.3).","Explain why the Father is not sent, and how Son and Spirit are each sent invisibly (aa.4–5).","Distinguish visible missions (Incarnation; dove, tongues, breath) and explain their fittingness (a.7).","Draw out the consequences for the spiritual life: the indwelling of the Trinity, the gifts, and prayer."],
 prereq:["mission","indwelling","omnipresence","grace","gift","charity"],
 recall:[
  ["t3l4","How is God present in all things, and what special presence does he have in the just?","By essence, presence and power, as cause of their being; and in the just as the known in the knower and the beloved in the lover (q.8 a.3)."],
  ["t4l5","Why is the Holy Spirit called Gift?","Because a gift's reason is love, so love is the first gift; the Spirit proceeds as Love (q.38 a.2)."],
  ["t4l2","How did the Church come to know the eternal processions?","Through the economy, the sending of the Son and the Spirit in history (CCC 236)."],
  ["t6","What is sanctifying grace?","A created share in the divine nature (2 Pet 1:4), a habit of the soul that makes us children of God and able to merit eternal life."]],
 reading:{primary:[["ST I q.43 aa.1–8 (the mission of the divine persons)",NA("1043.htm")],["ST I-II q.68 aa.1–3 (the gifts of the Holy Spirit)",NA("2068.htm")],["Elizabeth of the Trinity, 'O my God, Trinity whom I adore' (1904)",'https://en.wikipedia.org/wiki/Elizabeth_of_the_Trinity'],["CCC 257–260, 1997–2000",'https://www.vatican.va/archive/ENG0015/__P18.HTM']],
  secondary:["Emery, G. (2007) The Trinitarian Theology of Saint Thomas Aquinas, ch. 13.","Dodds, M.J. (2008) The Unchanging God of Love, ch. 9.","Garrigou-Lagrange, R. (1937) The Three Ages of the Interior Life, vol. 1, ch. 4 ('The indwelling of the Blessed Trinity').","Torrell, J.-P. (2003) Saint Thomas Aquinas, vol. 2: Spiritual Master. Washington, DC: CUA Press, chs 3–5."]},
 scripture:[["John 14:23, we will come to him and make our abode with him",null],["Galatians 4:4–6, God sent his Son… God hath sent the Spirit of his Son",null],["1 Corinthians 6:19, your members are the temple of the Holy Ghost",null],["John 20:22, Receive ye the Holy Ghost",null]],
 sections:[
 {id:"s1",h:"1. What it means for God to be sent (q.43 aa.1–2)",html:`<p>Mission includes two things: a relation to the sender (the one sent comes <em>from</em> him) and a relation to the term (he comes to be <em>somewhere</em> in a new way). Among creatures, being sent can mean being commanded, counselled or produced. In God it can mean only <em>procession of origin</em>; so no inferiority is implied (a.1).</p>
<p>And it implies no change in the one sent. A divine person \"begins to exist where he was not before\" only in the sense that he begins to exist in a new way, by a new effect in the creature. The change is entirely on the creature's side.</p>
<p><strong>Eternal and temporal (a.2).</strong> Some words express only the eternal origin (procession, generation); others add a temporal effect (mission, giving). Mission = eternal procession + temporal effect.</p>
${RC("t3l5",`<p>T3 L5: God is <strong>immutable</strong>; changes said of him in Scripture are changes in creatures' relation to him, like the sun 'entering' a house. Mission applies the same rule: the Son 'comes' when a creature receives him in a new way.</p>`)}`,
  check:Q("Mission in God implies…",[["command by a superior","No: only procession of origin."],["eternal procession plus a new temporal effect in a creature","Correct: q.43 a.2."],["a change in the person sent","The change is in the creature."]],1)},
 {id:"s2",h:"2. The invisible mission: only by sanctifying grace (a.3)",html:`<p>God is already in all things by essence, presence and power. For a divine person to be sent, he must be present in a <em>new</em> way. Thomas argues that only sanctifying grace makes this possible:</p>
<div class="quote">"For God is in all things by His essence, power and presence, according to His one common mode, as the cause existing in the effects which participate in His goodness. Above and beyond this common mode, however, there is one special mode belonging to the rational nature wherein God is said to be present as the object known is in the knower, and the beloved in the lover."<span class="src">ST I q.43 a.3 · Dominican tr. (1920)</span></div>
<p>By knowing and loving, the soul \"attains to God Himself\". And \"since the rational creature by its operation of knowledge and love attains to God Himself, according to this special mode God is said not only to exist in the rational creature but also to dwell therein as in His own temple\". Only sanctifying grace gives this; so only by sanctifying grace is a divine person sent and does he dwell.</p>
${RC("t3l4",`<p>T3 L4 (q.8 a.3) introduced both modes of presence. Here they are named: the first is <strong>omnipresence</strong>, common to all creatures; the second is the <strong>indwelling</strong>, proper to the just. The Trinity does not move into the soul; the soul is raised to know and love the Trinity already there.</p>`)}
<p>Not only do we have the gifts; we possess the divine person. To possess is to have what we can freely use or enjoy, \"and to have the power of enjoying the divine person can only be according to sanctifying grace. And yet the Holy Ghost is possessed by man, and dwells within him, in the very gift itself of sanctifying grace. Hence the Holy Ghost Himself is given and sent\" (a.3). The Spirit is not only the giver of grace; he is himself given.</p>`,
  check:Q("By what alone does an invisible mission of a divine person occur?",[["Any natural gift","No."],["Sanctifying grace","Correct: q.43 a.3."],["Miracles","No."]],1)},
 {id:"s3",h:"3. Who is sent, and how (aa.4–6)",html:`<p><strong>The Father is not sent (a.4).</strong> Mission means coming from another; the Father is from no one. He comes and dwells (John 14:23: \"we will come to him\"), but is not sent.</p>
<p><strong>Son and Spirit both sent invisibly (a.5).</strong> \"The whole Trinity dwells in the mind by sanctifying grace\"; but only the Son and Spirit, who are from another, are sent. Their missions differ by the gifts that mark them:</p>
<div class="tablewrap"><table class="t"><thead><tr><th>Mission of the Son</th><th>Mission of the Spirit</th></tr></thead><tbody>
<tr><td>Marked by gifts of the intellect, but not any knowledge: \"the intellectual illumination, which breaks forth into the affection of love\" (ad 2)</td><td>Marked by the gift of charity, the love that conforms us to the Spirit who is Love</td></tr>
<tr><td>Assimilates us to the Word</td><td>Assimilates us to Love</td></tr></tbody></table></div>
<p><strong>To all in grace (a.6).</strong> Every person in grace receives these missions, and there are new missions whenever someone advances in grace: to a new act of virtue, a new state of grace, the grace of miracles, prophecy, martyrdom, or a heroic act of charity (ad 2).</p>
${RC("t4l3",`<p>L3: the Son is the Word, but not any word: the Word "breathing forth Love" (verbum spirans amorem). So his mission is not mere information but knowledge that kindles love. Thomas's phrase in q.43 a.5 ad 2 ("illumination, which breaks forth into the affection of love") is the spiritual meaning of the psychological analogy.</p>`)}`,
  check:Q("The mission of the Son is marked by…",[["any knowledge at all","No."],["a knowledge that breaks forth into love","Correct: q.43 a.5 ad 2."],["miracles only","No."]],1)},
 {id:"s4",h:"4. Visible missions (aa.7–8)",html:`<p>\"God provides for all things according to the nature of each thing. Now the nature of man requires that he be led to the invisible by visible things\" (a.7). So the invisible missions are manifested visibly.</p>
<ul><li><strong>The Son</strong> is sent visibly in the Incarnation: not as a sign only, but as the one who personally assumes a human nature. He is sent as the author of sanctification.</li>
<li><strong>The Spirit</strong> is sent visibly in signs: the dove at the Jordan (signifying fruitfulness, his gift to the baptised), the bright cloud at the Transfiguration, the breath on Easter evening (\"Receive ye the Holy Ghost\", John 20:22), and the tongues of fire at Pentecost (signifying teaching and charity). He is shown as the sign of sanctification, not personally united to the dove or fire.</li></ul>
<p><strong>Who sends?</strong> The Son is sent by the Father; the Spirit by Father and Son (a.8). Thomas allows that the Son, as man, is also sent by the Spirit (Isa 61:1: \"The Spirit of the Lord is upon me\").</p>
${RC("t1",`<p>T1: revelation comes "in deeds and words having an inner unity" (Dei Verbum 2). The visible missions are those deeds: the Incarnation and Pentecost are not illustrations of a doctrine; they are the doctrine happening.</p>`)}`,
  check:Q("Why does the Spirit's visible mission use signs like the dove and fire?",[["Because the Spirit became a dove","No: not personally united."],["Because man is led to invisible things by visible ones","Correct: q.43 a.7."],["Because the Spirit is less than the Son","No."]],1)},
 {id:"s5",h:"5. The life of grace is Trinitarian",html:`<p>The treatise on the Trinity ends not in speculation but in the soul. Thomas's last word (q.43) is that the God whose inner life he has studied comes to dwell in the believer.</p>
<ul><li><strong>Baptism</strong> is \"in the name of the Father and of the Son and of the Holy Ghost\" (Matt 28:19): the first invisible mission, and the soul made a temple (1 Cor 6:19).</li>
<li><strong>Adoption.</strong> \"God sent his Son… that we might receive the adoption of sons. And because you are sons, God hath sent the Spirit of his Son into your hearts, crying: Abba, Father\" (Gal 4:4–6). The two missions make us children of the Father.</li>
<li><strong>The gifts of the Holy Spirit</strong> (I-II q.68) are dispositions by which the soul becomes docile to the Spirit's movement, as sails to the wind.</li></ul>
${RC("t9a",`<p>T9a: <strong>contemplation</strong> is a loving gaze on divine truth. The indwelling shows where it looks: not outward to a distant God, but inward to the Trinity present by grace. Teresa of Avila's 'interior castle' and Elizabeth of the Trinity's prayer ('O my God, Trinity whom I adore… make my soul your heaven') are the mystics' reading of q.43.</p>`)}
<div class="co check"><div class="co-h">Self-test: T4 in five sentences</div><p>(1) There are two processions in God, by intellect and will (L3). (2) They give four real relations identical with the essence (L1, L4). (3) Three of them, opposed, are subsisting relations: the persons (L4). (4) The Spirit proceeds from Father and Son as one principle (L5). (5) The Son and Spirit are sent into the world and into the soul, where the whole Trinity dwells by grace (L7). Can you explain each without notes?</p></div>
<div class="co bridge"><div class="co-h">Psychology · God-attachment</div><p>Attachment research has studied believers' relationship to God as an attachment figure, finding correspondence and compensation pathways with human attachment (Granqvist &amp; Kirkpatrick, 2016, in Cassidy &amp; Shaver, <em>Handbook of Attachment</em>, 3rd edn). The doctrine of the indwelling frames this theologically: God is not only a figure to approach, but a presence within, 'more inward than my inmost'. Clinicians working with religious clients can explore both images respectfully (P5).</p></div>`,
  check:Q("According to Galatians 4:4–6, what do the two missions accomplish?",[["They make us angels","No."],["They make us adopted sons crying 'Abba, Father'","Correct."],["They make the Father be sent","The Father is not sent."]],1)}
 ],
 quiz:[
  Q("Mission in God implies…",[["inferiority of the one sent","No: only origin."],["procession of origin with a new temporal effect","Correct: q.43 aa.1–2."],["local motion","No."],["creation of a person","No."]],1,"ST I q.43",{bloom:"Understand",terms:["mission"],diff:1}),
  Q("When a divine person is sent, what changes?",[["The person sent","No."],["The creature, which receives a new effect","Correct."],["The Father","No."],["Nothing at all","The creature changes."]],1,"ST I q.43 a.2",{bloom:"Understand",terms:["mission","immutability"],diff:2}),
  Q("God dwells 'as in his own temple' in…",[["every creature","By essence, presence, power, not as temple."],["the rational creature in grace, who knows and loves him","Correct: q.43 a.3."],["only churches","No."],["only angels","No."]],1,"ST I q.43 a.3",{bloom:"Remember",terms:["indwelling"],diff:1}),
  Q("Why is the Father not sent?",[["He is too great","Not the reason."],["Mission means being from another, and the Father is from no one","Correct: q.43 a.4."],["He does not dwell in the soul","He does dwell."],["He sends himself","No."]],1,"ST I q.43 a.4",{bloom:"Understand",terms:["mission"],diff:2}),
  Q("'We will come to him and will make our abode with him' (John 14:23) shows that…",[["only the Son dwells","No."],["the whole Trinity dwells in the soul by grace","Correct: q.43 a.5."],["the Father is sent","He comes, not sent."],["God is far away","No."]],1,"John 14:23",{bloom:"Apply",terms:["indwelling"],diff:2}),
  Q("The mission of the Spirit is marked by the gift of…",[["prophecy only","No."],["charity","Correct."],["miracles","No."],["knowledge alone","That relates to the Son."]],1,"ST I q.43 a.5",{bloom:"Remember",terms:["charity"],diff:1}),
  Q("New invisible missions occur when…",[["a person advances in grace or receives a new gift","Correct: q.43 a.6 ad 2."],["the liturgical year changes","No."],["a person sins","No."],["never after baptism","No."]],0,"ST I q.43 a.6",{bloom:"Understand",terms:["mission"],diff:2}),
  Q("The Son's visible mission differs from the Spirit's because…",[["the Son is personally united to the human nature, the Spirit is not united to the dove","Correct."],["the Spirit was never visible","He was shown in signs."],["the Son was a dove","No."],["there is no difference","There is."]],0,"ST I q.43 a.7",{bloom:"Analyse",terms:["mission"],diff:3}),
  Q("Visible missions are fitting because…",[["God is visible","No."],["man is led to invisible things through visible ones","Correct: q.43 a.7."],["angels asked for them","No."],["they replace grace","No."]],1,"ST I q.43 a.7",{bloom:"Understand",terms:[],diff:1}),
  Q("'Because you are sons, God hath sent the Spirit of his Son into your hearts' is from…",[["Romans 5","No."],["Galatians 4:6","Correct."],["John 14","No."],["Acts 2","No."]],1,"Gal 4:6",{bloom:"Remember",terms:[],diff:1})
 ],
 construct:{q:"Whether the invisible mission of the divine person is only according to the gift of sanctifying grace?",ref:"ST I q.43 a.3",
  model:{obj:"It seems not: the Son is sent whenever he is known, and he is known also by gifts that are not sanctifying, such as prophecy; further, the Spirit is said to be given by the gift of miracles.",sc:"Augustine: the Spirit proceeds temporally for the creature's sanctification; but mission is temporal procession; so mission is only by sanctifying grace.",resp:"A divine person is sent when he exists in someone in a new way and is possessed. God is in all things by essence, power and presence, as cause. Beyond this there is a special mode, proper to the rational creature, in which God is present as known in the knower and beloved in the lover, and dwells as in his temple. This is only by sanctifying grace. So the mission is only by sanctifying grace.",rep:"Gifts like prophecy and miracles manifest grace but do not of themselves make God dwell in the soul; where they accompany grace, the mission is by the grace, not by them."},
  rubric:["Objection argues from gifts such as prophecy or miracles.","Sed contra: mission is for sanctification.","Respondeo distinguishes the common mode of presence from the special mode.","Respondeo: special mode = known and loved, as in a temple, by grace only.","Reply: charismatic gifts do not by themselves constitute the indwelling."]},
 drill:{title:"Order the steps of the soul's life in the Trinity",parts:["Baptism in the name of the Father, Son and Holy Spirit","Sanctifying grace: the soul becomes a temple","The invisible missions of Son and Spirit","Knowledge breaking forth into love","Adoption: crying 'Abba, Father'"]},
 connections:`<p><strong>Back.</strong> T3 L4 (two modes of presence), T3 L5 (immutability), T4 L3 (the Word breathing Love), L5 (Gift).</p><p><strong>Forward.</strong> T5–T6 (grace and the gifts), T7 (charity), T9a (contemplation), T11 (the visible mission of the Son: the Incarnation), T13 (Baptism and Confirmation), T15 (the beatific vision as the consummation of the missions).</p><p><strong>Psychology.</strong> Section 5 on attachment to God.</p>`}
]);

Object.assign(EXTRAS,{
 t4l2:{plain:{version:"Christians did not invent the Trinity by speculation. God showed it by sending his Son and his Spirit. Then, when people denied that the Son or the Spirit is truly God, councils found precise words to protect what Scripture teaches.",question:"Where does the doctrine of the Trinity come from?",one:"The Trinity was revealed through the missions of the Son and the Spirit and defined at Nicaea and Constantinople: one ousia, three hypostaseis."},
  hook:"\"Arius denied → Nicaea defined the Son (325) → Constantinople the Spirit (381)\".",
  analogy:{title:"A fence around a field",text:"The councils' words are not a cage around the mystery but a fence around a field: they mark where error lies, so that the faithful can roam freely inside."},
  sort:{title:"Who said it?",cats:["Arius","Nicaea / Athanasius","Cappadocians","Augustine"],items:[["There was when he was not",0],["Consubstantial (homoousios) with the Father",1],["One ousia, three hypostaseis",2],["The mind remembers, understands and loves itself",3],["The Son is the first creature",0],["The Spirit is glorified with the Father and the Son (Basil)",2]]}},
 t4l3:{plain:{version:"When you understand something, a 'word' forms inside your mind without leaving it. Thomas uses this to show how the Son can come from the Father and still be one with him. Love, too, proceeds within the lover: that is the Spirit.",question:"How can the Son come from the Father without being a creature?",one:"The Son proceeds as the Word of the Father's self-knowledge, the Spirit as the Love of his will; both remain within God."},
  hook:"\"Word by way of likeness; Love by way of impulse\".",
  analogy:{title:"The word you have not yet spoken",text:"Before you say a sentence, you already 'have' its meaning in mind. That inner meaning comes from you and stays in you. The Father's Word is like that, except that it is not a passing thought but a person, as eternal as he is."},
  sort:{title:"Intellect or will?",cats:["Procession by intellect","Procession by will"],items:[["Word",0],["Love",1],["Image",0],["Gift",1],["Generation",0],["Spiration",1]]}},
 t4l4:{plain:{version:"In God, everything is one except what is distinguished by relations: Father to Son, Father and Son to Spirit. These relations are not add-ons; each one subsists. That is what a divine person is. So we must speak carefully: the Son is 'someone else' than the Father, but not 'something else'.",question:"What is a person in God, and how should we speak about three and one?",one:"A divine person is a subsisting relation; one essence, two processions, three persons, four relations, five notions."},
  hook:"\"1-2-3-4-5\": one essence, two processions, three persons, four relations, five notions.",
  analogy:{title:"North and south",text:"North and south are the same line, really distinct as directions, because each is defined by being opposite to the other. Father and Son are the same God, really distinct as persons, because each is what he is by relation to the other."},
  sort:{title:"Allowed or not?",cats:["Correct speech","Avoid"],items:[["The Son is other (alius) than the Father",0],["The Son is another thing (aliud) than the Father",1],["God begets God",0],["The essence begets the essence",1],["Three persons, one God",0],["Three Gods",1],["Distinction of persons",0],["Division of God",1]]}},
 t4l5:{plain:{version:"The Holy Spirit is the Love of the Father and the Son, and the first Gift through which every other gift is given. The Latin Church confesses that he proceeds from the Father and the Son; the Greek Fathers say 'from the Father through the Son'. Rightly understood, both express the same faith.",question:"Who is the Holy Spirit, and why do East and West disagree about the Filioque?",one:"The Spirit proceeds from the Father and the Son as from one principle (or from the Father through the Son); he is personal Love and the first Gift."},
  hook:"\"Opposed relations distinguish: so the Spirit must be from the Son\".",
  analogy:{title:"The kiss",text:"Bernard of Clairvaux called the Spirit the kiss of the Father and the Son: it comes from both together, is one, and is their love made, as it were, a third. The image is devotional, but it captures 'one principle'."},
  sort:{title:"East, West, or both?",cats:["Latin formula","Greek formula","Shared"],items:[["From the Father and the Son",0],["From the Father through the Son",1],["The Father is the source of the Godhead",2],["One principle, one spiration",0],["Ekporeusis from the Father alone",1],["The Spirit is Lord and giver of life",2]]}},
 t4l6:{plain:{version:"The three persons are perfectly equal and eternal; there is an order of origin but no 'first' or 'greater'. Each is wholly in the others. When we link power to the Father, wisdom to the Son and goodness to the Spirit, we are 'appropriating': it helps us see the persons, though all three share every attribute.",question:"Are the three persons equal, and why do we link certain attributes with each?",one:"Equal in all things, distinct by origin, each in each (perichoresis); appropriations manifest the persons without dividing the essence."},
  hook:"\"Of him, by him, in him\" (Rom 11:36): Father, Son, Spirit.",
  analogy:{title:"Three candles, one light",text:"Three candles in a room give one light in which you cannot tell where one flame's light ends. The image is imperfect (the candles are three things), but it suggests equal, inseparable, mutually pervading persons."},
  sort:{title:"Match the appropriation to the person",cats:["Father","Son","Holy Spirit"],items:[["Power",0],["Wisdom",1],["Goodness",2],["Eternity",0],["Beauty",1],["Concord",2],["Of whom",0],["By whom",1],["In whom",2]]}},
 t4l7:{plain:{version:"The Son and the Spirit are 'sent' into the world: the Son by becoming man, the Spirit at Pentecost. They are also sent invisibly into every soul in grace, where the whole Trinity comes to live as in a temple, known and loved.",question:"How does the Trinity come into our lives?",one:"By sanctifying grace the whole Trinity dwells in the soul; the Son and Spirit are sent there, as known and loved."},
  hook:"\"Mission = eternal procession + new presence in a creature\".",
  analogy:{title:"Opening the shutters",text:"The sun is already shining on the house; when the shutters open, it is 'in' the room in a new way. God is already present to the soul as cause; grace opens the shutters, and he dwells there as known and loved."},
  sort:{title:"Visible or invisible mission?",cats:["Visible","Invisible"],items:[["The Incarnation",0],["The dove at the Jordan",0],["Grace given in Baptism",1],["Tongues of fire at Pentecost",0],["Growth in charity",1],["The breath on Easter evening",0]]}}
});
